            if val_a != val_b:
                diff_points.append({
                    'index': i,
                    'class_a_mro_at_index': val_a,
                    'class_b_mro_at_index': val_b
                })
        return {
            'mro_class_a': mro_a,
            'mro_class_b': mro_b,
            'common_prefix_length': common_prefix_len,
            'first_divergence_point': diff_points[0] if diff_points else None,
            'total_differences': len(diff_points)
        }
