    if not (math.isinf(a) or math.isnan(a)) and not (math.isinf(b) or math.isnan(b)):
        return a > b
    elif math.isinf(a):
        if math.copysign(math.inf, a) == 1.0:
            return True
        else:
            return False
    elif math.isnan(a):
        return False
def compare_strings(a: str, b: str) -> bool:
    try:
        return a > b
    except TypeError:
        raise ValueError("Both arguments must be strings")
