    result_ge = brancher.branch('ge', arr_a, np.array([2.0, 4.5, 6.0]))
    expected_ge = np.array([True, False, True])
    assert np.allclose(result_ge, expected_ge), "Vectorized GE failed"
    print("All tests passed.")

