        return Image.fromarray(np.array(new_image), 'I')
    elif stats['min'] < 30 or stats['max'] > 240:
        new_image = image.convert('L').point(lambda x: min(255, max(0, int(x * (1 + ((stats['mean'] - 128) / std_dev))))) if 'std' in locals() else None)
    return image
