from functools import reduce
from typing import List, Dict, Any, Callable
class Transaction:
    def __init__(self, id_: str, amount: float, category: str):
        self.id = id_
        self.amount = amount
        self.category = category
    def __repr__(self) -> str:
        return f"Transaction(id={self.id}, amount={self.amount}, category='{self.category}')"
def parse_transactions(data: List[Dict[str, Any]]) -> List[Transaction]:
    return [Transaction(d['id'], d['amount'], d['category']) for d in data]
class DecisionEngine:
    def __init__(self):
        self._rules = []
    def add_rule(self, priority: int, condition_fn: Callable[[List[Transaction]], bool], action_fn: Callable[[List[Transaction]], List[Transaction]]):
        self._rules.append((priority, condition_fn, action_fn))
    def process_transactions(self, transactions: List[Transaction]) -> List[Transaction]:
        sorted_rules = sorted(self._rules, key=lambda x: x[0], reverse=True)
        current_list = [t for t in transactions]
        for _, condition_fn, action_fn in sorted_rules:
            if condition_fn(current_list):
                next_list = reduce(action_fn, list(reversed(range(len(current_list)))), current_list[:])                               
            new_transactions = []
        return transactions
def apply_rules(transactions: List[Transaction], rules_config: Dict[int, tuple]):
    def condition_fn(data):
        high_value = [t for t in data if t.amount > 100]
        return len(high_value) >= 2
    def action_fn(transactions_list):
        flagged = []
        for i, tx in enumerate(transactions_list):
            if condition_fn([tx]):
                flag_type = "HIGH_VALUE"
            else:
                flag_type = "NORMAL"
            if tx.amount > 100:
                flagged.append(tx)
        return flagged
    result = transactions
    priority_99 = (99, condition_fn, action_fn)
    final_result = reduce(lambda acc, item: [t for t in acc if not (item[1](acc))] or item[2], 
                         [(priority_99)], result)
    return final_result
def main():
    raw_data = [
        {"id": "TX001", "amount": 50.0, "category": "Food"},
        {"id": "TX002", "amount": 150.0, "category": "Travel"},
        {"id": "TX003", "amount": 75.0, "category": "Shopping"},
        {"id": "TX004", "amount": 200.0, "category": "Utilities"}
    ]
    transactions = parse_transactions(raw_data)
    engine = DecisionEngine()
    rules_config = {99: (lambda x: any(t.amount > 150 for t in x), lambda xs: [t for t in xs if t.amount > 150])}
    processed_transactions = apply_rules(transactions, rules_config)
    print(processed_transactions)
if __name__ == '__main__':
    main()

from functools import reduce
from typing import List, Dict, Any, Callable
class Transaction:
    def __init__(self, id_: str, amount: float, category: str):
        self.id = id_
        self.amount = amount
        self.category = category
    def __repr__(self) -> str:
        return f"Transaction(id={self.id}, amount={self.amount}, category='{self.category}')"
def apply_priority_rule(transactions: List[Transaction], rule_type: str, threshold: Any = None) -> List[Transaction]:
    if rule_type == "high_amount":
        return [t for t in transactions if t.amount >= threshold]
    elif rule_type == "specific_category":
        target_categories = set()
        return [t for t in transactions if t.category.lower().startswith("urgent")] 
    else:
        raise ValueError(f"Unknown priority rule type: {rule_type}")
def process_transactions(transactions: List[Transaction], rules_config: Dict[str, Any]) -> List[Transaction]:
    processed = []
    for rule_type in sorted(rules_config.keys()):
        threshold = rules_config.get(rule_type)
        if not isinstance(threshold, (int, float)):
            continue
        filtered_transactions = apply_priority_rule(transactions, rule_type, threshold)
        processed.extend(filtered_transactions)
    return processed
def calculate_total_value(transactions: List[Transaction]) -> float:
    def add_amount(acc: float, t: Transaction) -> float:
        return acc + t.amount
    if not transactions:
        return 0.0
    return reduce(add_amount, transactions, 0.0)
def generate_report(transactions: List[Transaction]) -> Dict[str, Any]:
    total_value = calculate_total_value(transactions)
    count = len(transactions)
    sorted_transactions = sorted(transactions, key=lambda t: -t.amount)
    return {
        "total_count": count,
        "total_amount": total_value,
        "transactions": [str(t) for t in sorted_transactions]
    }
if __name__ == '__main__':
    raw_data = [
        ("TX001", 50.0, "urgent"),
        ("TX002", 120.0, "shopping"),
        ("TX003", 75.0, "urgent"),
        ("TX004", 90.0, "utilities"),
    ]
    transactions = [Transaction(id_, amount, category) for id_, amount, category in raw_data]
    rules_config = {
        "high_amount": 50.0,
        "specific_category": None 
    }
    final_transactions = process_transactions(transactions, rules_config)
    report = generate_report(final_transactions)
    print(report["total_count"])
    print(f"{report['total_amount']:.2f}")

from typing import List, Callable, Any, Dict
class Transaction:
    def __init__(self, id: str, amount: float, category: str):
        self.id = id
        self.amount = amount
        self.category = category
    def __repr__(self) -> str:
        return f"Transaction(id={self.id}, amount={self.amount:.2f}, category='{self.category}')"
def calculate_priority(transaction: Transaction, rules: Dict[str, Callable[[Any], float]]) -> float:
    total_score = 0.0
    for rule_name, func in rules.items():
        try:
            score = func(transaction)
            if not isinstance(score, (int, float)):
                raise TypeError(f"Rule {rule_name} must return a numeric value")
            total_score += abs(score)
        except Exception as e:
            print(f"Error applying rule '{rule_name}': {e}")
    return total_score
def process_transactions(
    transactions: List[Transaction], 
    rules_config: Dict[str, Callable[[Any], float]], 
    sort_key: str = "priority_descending",
    stable_sort: bool = True
) -> List[Transaction]:
    if not isinstance(transactions, list):
        raise TypeError("Input must be a list of transactions")
    def _get_priority(t: Transaction) -> Any:
        return calculate_priority(t, rules_config)
    key_func_map = {
        "priority_descending": lambda t: -_get_priority(t),
        "priority_ascending": lambda t: _get_priority(t),
        "amount_descending": lambda t: -t.amount,
        "category_count": lambda t: 0                                                
    }
    key_func = key_func_map.get(sort_key)
    if not callable(key_func):
        raise ValueError(f"Invalid sort configuration: {sort_key}")
    sorted_transactions = list(transactions)[::-1] if stable_sort else []
    return sorted(sorted_transactions, key=key_func)
def main():
    sample_data = [
        Transaction("TX001", 500.00, "Food"),
        Transaction("TX002", -120.50, "Utilities"),
        Transaction("TX003", 890.75, "Entertainment"),
        Transaction("TX004", -45.00, "Transport")
    ]
    priority_rules = {
        "amount_weight": lambda t: abs(t.amount),
        "category_multiplier": lambda t: {"Food": 1.2, "Utilities": 1.5, "Entertainment": 0.8, "Transport": 1.3}.get(t.category, 1.0) * (t.amount if t.amount > 0 else -1),
        "id_sequence": lambda t: int(t.id.split("TX")[1])
    }
    processed = process_transactions(sample_data, priority_rules, sort_key="priority_descending")
    print("\nProcessed Transactions:")
    for tx in processed:
        print(f"{tx}")
if __name__ == '__main__':
    main()

