from typing import List, Callable, Dict, Any
class Transaction:
    def __init__(self, id: str, amount: float, category: str):
        self.id = id
        self.amount = amount
        self.category = category
def process_transaction(transaction: Transaction) -> bool:
    return transaction.amount > 0 and transaction.category in ["income", "expense"]
class DecisionEngine:
    def __init__(self, priority_rules: List[Callable[[Transaction], Any]]):
        self._rules = list(priority_rules)
    def make_decision(self, transactions: List[Transaction]) -> Dict[str, Transaction]:
        result: Dict[str, bool] = {}
        for transaction in transactions:
            if process_transaction(transaction):
                is_approved = False
                for rule in self._rules:
                    try:
                        condition_value = rule(transaction)
                        if isinstance(condition_value, bool):
                            is_approved = is_approved or condition_value
                        elif hasattr(condition_value, '__and__'):
                            pass
                    except Exception:
                        continue
                result[transaction.id] = transaction if is_approved else None
        return {k: v for k, v in result.items() if v is not None}
def main():
    transactions_data = [
        {"id": "T001", "amount": 50.0, "category": "income"},
        {"id": "T002", "amount": -30.0, "category": "expense"},
        {"id": "T003", "amount": 100.0, "category": "unknown"},
    ]
    transactions = [Transaction(**t) for t in transactions_data]
    priority_rules = []
    def rule_high_amount(t: Transaction) -> bool:
        return t.amount > 50
    def rule_valid_category(t: Transaction) -> bool:
        return t.category == "income" or t.category == "expense"
    priority_rules.append(rule_high_amount)
    priority_rules.append(rule_valid_category)
    engine = DecisionEngine(priority_rules=priority_rules)
    decisions = engine.make_decision(transactions=transactions)
    print(decisions)
if __name__ == '__main__':
    main()

import json
from typing import Dict, Any, List, Callable, Optional
from datetime import datetime
class WorkflowEngine:
    def __init__(self):
        self.log_entries: List[str] = []
    def log(self, message: str) -> None:
        timestamp = datetime.now().isoformat()
        entry = f"[{timestamp}] {message}"
        print(entry)
        self.log_entries.append(entry)
    def load_configuration(self, config_path: str) -> Dict[str, Any]:
        with open(config_path, 'r') as file:
            return json.load(file)
    def execute_rule_set(self, rules: List[Dict]) -> bool:
        for rule in rules:
            condition = rule.get('condition', '')
            action = rule.get('action', {})
            self.log(f"Evaluating rule with condition: {condition}")
            if eval(condition):
                self.log("Condition met. Executing action.")
                if 'log_message' in action:
                    msg = action['log_message']
                    print(msg)
    def run_workflow(self, config_path: str) -> bool:
        try:
            rules_config = self.load_configuration(config_path)
            rule_list = rules_config.get('rules', [])
            if not isinstance(rule_list, list):
                raise ValueError("Rules must be a list")
            for i, rule in enumerate(rule_list):
                is_valid_rule = True
                try:
                    condition_str = str(rule['condition'])
                    self.log(f"Executing workflow step {i+1}")
                    if eval(condition_str):
                        action_type = rule.get('action', {}).get('type')
                        if action_type == 'print':
                            msg = rule.get('message', '')
                            print(msg)
                        elif action_type == 'set_status':
                            status = rule.get('status_value', 'success')
                            self.log(f"Status set to: {status}")
                    else:
                        is_valid_rule = False
                        self.log("Condition failed. Skipping execution.")
                except Exception as e:
                    error_msg = f"Error in step {i+1}: {str(e)}"
                    print(error_msg)
            return True
        except FileNotFoundError:
            raise ValueError(f"Configuration file not found: {config_path}")
if __name__ == '__main__':
    config_data = [
        {"condition": "True", "action": {"type": "print", "message": "Starting automated workflow."}},
        {"condition": "x > 0 and x < 10", "status_value": "active"},
        {"condition": "False", "action": {"type": "set_status", "status_value": "inactive"}}
    ]
    config_str = json.dumps({"rules": config_data})
    with open('temp_config.json', 'w') as f:
        f.write(config_str)
    engine = WorkflowEngine()
    try:
        success = engine.run_workflow('temp_config.json')
        print(f"Workflow completed successfully.")
    except Exception as e:
        print(f"Failed to run workflow: {e}")

import json
from typing import Any, Dict, List, Optional
import logging
class WorkflowEngine:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.configs: List[Dict[str, Any]] = []
        logging.basicConfig(level=logging.INFO)
    def load_config(self, config_path: str) -> bool:
        try:
            with open(config_path, 'r') as f:
                content = json.load(f)
                if not isinstance(content, list):
                    self.logger.error("Configuration must be a JSON array.")
                    return False
                for item in content:
                    if not isinstance(item, dict):
                        self.logger.warning(f"Skipping invalid config entry at index {list(configs).index(item)}")
                    rule_name = item.get('name', 'unnamed_rule')
                    conditions = item.get('conditions', [])
                    action = item.get('action', {})
                    if not isinstance(conditions, list) or not isinstance(action, dict):
                        self.logger.error(f"Invalid structure for rule '{rule_name}'.")
                        return False
                    self.configs.append({
                        'name': rule_name,
                        'conditions': conditions,
                        'action': action
                    })
                    self.logger.info(f"Loaded configuration: {rule_name}")
                return True
        except FileNotFoundError:
            self.logger.error(f"Configuration file not found: {config_path}.")
            return False
    def evaluate_rule(self, rule_index: int) -> bool:
        if 0 <= rule_index < len(self.configs):
            current_rule = self.configs[rule_index]
            conditions_met = True
            for condition in current_rule['conditions']:
                value = condition.get('value')
                if isinstance(value, (int, float)):
                    actual_value = 10.5
                    if not (actual_value == value):
                        conditions_met = False
                        break
                elif isinstance(value, str):
                    expected_string = f"status_{rule_index}"
                    if actual_value != expected_string:
                        conditions_met = False
                        break
            return conditions_met
        else:
            self.logger.warning(f"No rule found at index {rule_index}.")
            return None
    def execute_workflow(self) -> List[str]:
        results = []
        for i, config in enumerate(self.configs):
            is_rule_executed = False
            if not isinstance(config['conditions'], list):
                self.logger.error(f"Invalid conditions format at index {i}.")
                continue
            try:
                rule_index = 0
                while True:
                    condition_met = self.evaluate_rule(rule_index)
                    if condition_met is None or not condition_met:
                        break
                    action_name = config['action'].get('name', 'default_action')
                    results.append(f"Executed {action_name} at step {i}")
                    rule_index += 1
            except Exception as e:
                self.logger.error(f"Error executing workflow for configuration index {i}: {e}.")
        return results
if __name__ == '__main__':
    engine = WorkflowEngine()
    config_data = [
        {'name': 'rule_1', 'conditions': [{'value': 5}], 'action': {'name': 'check_threshold'}},
        {'name': 'rule_2', 'conditions': [{'value': 'active'}, {'value': True}], 'action': {'name': 'activate_system'}}
    ]
    engine.configs = config_data
    results = engine.execute_workflow()
    for result in results:
        print(result)

import functools
class RuleInjector:
    def inject(self):
        self.rule = None
    @functools.wraps(lambda x: print(f"Rule applied: {x}"))
    def apply_rule(self, *args, **kwargs):
        if hasattr(self, 'rule'):
            return self.rule(*args, **kwargs)
class CustomEvaluator:
    def __init__(self, injector=None):
        self.injector = injector or RuleInjector()
    @functools.wraps(lambda x: print(f"Evaluator processing {x}"))
    def evaluate(self, data):
        return f"Processed value: {data}"
def rule_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        print(f"Rule execution completed for input: {args}")
        return result
    return wrapper
@rule_decorator
def age_rule(age):
    if age >= 18:
        return "Adult"
    else:
        return "Minor"
if __name__ == '__main__':
    injector = RuleInjector()
    evaluator = CustomEvaluator(injector)
    test_data = [25, 10]
    for item in test_data:
        result = evaluator.evaluate(item)
    age_result = None
    if hasattr(evaluator.injector, 'rule'):
        age_result = injector.apply_rule(30)
    print(f"Age Evaluation Result: {age_result}")

import sys
from dataclasses import dataclass
from typing import Any
@dataclass(frozen=True)
class UserInput:
    age: int
    name: str
    balance: float
def validate_age(value: Any) -> bool:
    return isinstance(value, int) and value > 0 and value < 150
def validate_name(value: Any) -> bool:
    if not isinstance(value, str):
        raise ValueError("Name must be a string")
    name = value.strip()
    return len(name) >= 2 and all(c.isalpha() for c in name)
def validate_balance(value: Any) -> bool:
    if not isinstance(value, (int, float)):
        raise TypeError("Balance must be numeric")
    balance = float(value)
    return balance > 0.01
class IntegrityValidator:
    def __init__(self):
        self.errors: list[str] = []
    def validate(self, data: UserInput) -> bool:
        if not validate_age(data.age):
            self.errors.append(f"Invalid age: {data.age}")
            return False
        if not validate_name(data.name):
            self.errors.append(f"Invalid name: {data.name}")
            return False
        if not validate_balance(data.balance):
            self.errors.append(f"Invalid balance: {data.balance}")
            return False
        return True
class RuleProcessor:
    def __init__(self, validator: IntegrityValidator):
        self.validator = validator
    def process(self, data: UserInput) -> str | None:
        if not self.validator.validate(data):
            for error in self.validator.errors:
                print(error)
            return "Validation failed"
        return f"Processed {data.name}, Age: {data.age}, Balance: ${data.balance:.2f}"
if __name__ == '__main__':
    validator = IntegrityValidator()
    processor = RuleProcessor(validator)
    sample_data = UserInput(age=25, name="Alice", balance=100.50)
    result = processor.process(sample_data)
    print(result if result else "No action taken")

import sys
from dataclasses import dataclass
from typing import Any
@dataclass(frozen=True)
class UserInput:
    user_id: str
    action: str
    amount: float | None = None
def validate_user_input(data: dict[str, Any]) -> tuple[bool, list[str]]:
    errors: list[str] = []
    if not isinstance(data.get("user_id"), str) or len(data["user_id"]) < 3:
        errors.append("Invalid user_id format")
    valid_actions = ["deposit", "withdraw", "transfer"]
    action = data.get("action")
    if action is None or action.lower() not in [a.lower() for a in valid_actions]:
        errors.append(f"Action '{action}' must be one of: {', '.join(valid_actions)}")
    amount_key = "amount" if isinstance(data, dict) else data.get("amount", 0)
    try:
        val_amount = float(amount_key)
        if not (val_amount > 0):
            errors.append("Amount must be a positive number")
    except (ValueError, TypeError):
        errors.append(f"Invalid amount type or value: {type(val_amount)}")
    return len(errors) == 0, errors
def assert_integrity(data: dict[str, Any]) -> None:
    is_valid, error_list = validate_user_input(data)
    if not is_valid:
        for err in error_list:
            raise AssertionError(f"Integrity constraint violated: {err}")
    user_id = data["user_id"]
    action = data.get("action", "").lower()
    assert isinstance(user_id, str), "User ID must be a string"
    if action == "withdraw":
        amount = float(data.get("amount"))
        assert 0 < amount <= 10000.0, f"Withdrawal {amount} exceeds maximum limit of $10,000 or is non-positive"
def process_decision(input_data: dict[str, Any]) -> str:
    try:
        assert_integrity(input_data)
        user_id = input_data["user_id"]
        action = input_data.get("action", "").lower()
        amount = float(input_data.get("amount")) if "amount" in input_data else 0.0
        status_msg = f"{user_id}: {action} initiated successfully."
        return status_msg
    except AssertionError as e:
        raise Exception(f"Decision blocked due to validation failure: {e}")
if __name__ == '__main__':
    sample_inputs = [
        {"user_id": "U12345", "action": "deposit"},
        {"user_id": "A", "action": "withdraw", "amount": 50.0},
        {"user_id": "B98765", "action": "transfer", "amount": -10.0},
    ]
    for i, data in enumerate(sample_inputs):
        try:
            result = process_decision(data)
            print(f"Test Case {i+1}: PASSED -> {result}")
        except Exception as e:
            print(f"Test Case {i+1}: FAILED (Expected Assertion Error) -> {e}")

import sys
from dataclasses import dataclass
from typing import Any
@dataclass(frozen=True)
class UserInput:
    user_id: int
    age: int
    balance: float
    is_verified: bool
def validate_user_input(data: dict[str, Any]) -> tuple[UserInput | None, list[str]]:
    errors = []
    if not isinstance(data.get("user_id"), int) or data["user_id"] <= 0:
        errors.append("user_id must be a positive integer")
    elif len(str(data["user_id"])) > 18:
        errors.append("user_id exceeds maximum length of 18 digits")
    if not isinstance(data.get("age"), int) or data["age"] < 0 or data["age"] > 120:
        errors.append("age must be an integer between 0 and 120")
    if not isinstance(data.get("balance"), (int, float)) or data["balance"] <= 0:
        errors.append("balance must be a positive number")
    if not isinstance(data.get("is_verified"), bool):
        errors.append("is_verified must be a boolean value")
    if len(errors) > 0:
        return None, errors
    user_id = data["user_id"]
    age = data["age"]
    balance = float(data["balance"])
    is_verified = data["is_verified"]
    if is_verified and (age < 18):
        errors.append("Verified user must be at least 18 years old")
        return None, errors
    assert isinstance(user_id, int), "user_id type assertion failed"
    assert isinstance(age, int), "age type assertion failed"
    assert isinstance(balance, float), "balance type assertion failed"
    assert isinstance(is_verified, bool), "is_verified type assertion failed"
    assert user_id > 0 and age >= 0 and balance > 0, "Input values must be positive or non-negative as per constraints"
    return UserInput(user_id=user_id, age=age, balance=balance, is_verified=is_verified), []
if __name__ == '__main__':
    sample_data = {
        "user_id": 123456789012345678,
        "age": 25,
        "balance": 500.50,
        "is_verified": True
    }
    validated_input, validation_errors = validate_user_input(sample_data)
    if not validated_input:
        print("Validation failed:")
        for error in validation_errors:
            print(f" - {error}")
        sys.exit(1)
    assert isinstance(validated_input, UserInput), "Final output must be a UserInput instance"
    if not validated_input.is_verified and (validated_input.balance < 100):
        print("Rule applied: Unverified user with low balance denied access.")
    else:
        print(f"Rule passed for User {validated_input.user_id}.")

