        if len(non_null_indices) == 0 or len(set(extracted_values)) <= 2 and extracted_values.count(None) + len(set(v for v in extracted_values if v is not None)) == 1:
            continue
        unique_values = set()
        for val in extracted_values:
            if val is not None:
                unique_values.add(val)
