import json
def filter_consistent_groups(data):
    filtered = []
    for group in data:
        if 'numeric_values' not in group:
            continue
        values = [float(v) for v in group['numeric_values']]
        is_consistent = all(abs(values[i] - values[0]) < 1e-9 
                          for i in range(1, len(values)))
        if is_consistent:
            filtered.append(group)
    return filtered
