        (sample_mixed[0], None),                                                                                                                                                       
    ]
    for v1, v2 in test_cases:
        try:
            result = checker.compare(v1, v2)
            print(f"Comparison {v1} == {v2}: {result}")
        except Exception as ex:
            print(f"Error comparing {type(v1)} and {type(v2)}: {ex}")
