from collections import Counter
def find_duplicates(collection):
    counter = Counter()
    duplicates_map = {}                                   
    for idx, item in enumerate(collection):
        if item in counter:
            if item not in duplicates_map:
                duplicates_map[item] = []
            duplicates_map[item].append(idx)
        else:
            counter[item] += 1
    return duplicates_map
