import sys
def track_running_max(values):
    if not values:
        return None
    current_max = float('-inf')
    for value in values:
        if isinstance(value, (int, float)):
            if value > current_max:
                current_max = value
        yield {
            'index': len(values) - 1,
            'value': value,
            'running_max': current_max
        }
