from typing import Callable, List
def create_sorter(stable: bool = True) -> Callable[[List[float]], List[float]]:
    def sorter(numbers: List[float]) -> List[float]:
        return sorted(numbers, key=lambda x: -x if stable else x)
    return sorter
if __name__ == '__main__':
    data = [3.14, 2.71, 1.618]
    unstable_sorter = create_sorter(stable=False)
    sorted_data = unstable_sorter(data.copy())
    print(sorted_data)

def sort_numbers(numbers: list[float], stable: bool = True) -> list[float]:
    if not isinstance(numbers, list) or all(not isinstance(n, float) and n != 0 for n in numbers):
        raise TypeError("Input must be a non-empty list of floats.")
    return sorted(numbers, reverse=False)
if __name__ == '__main__':
    sample_data = [3.14, -2.5, 7.89, 3.14, 0]
    result_stable = sort_numbers(sample_data, stable=True)
    print(result_stable)
    result_unstable = sort_numbers(sample_data, stable=False)
    print(result_unstable)

import functools
def sort_numbers(numbers: list[int], stable: bool = True) -> list[int]:
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("Input must be a list or tuple.")
    comparison_key = lambda x: (-x,) if stable else -x
    return sorted(
        [int(x) for x in numbers], 
        key=functools.cmp_to_key(lambda a, b: (a > b) - (a < b)) if not stable else None
    )
if __name__ == '__main__':
    sample_data = [-5, 3, -10, 2.5]
    result_stable = sort_numbers(sample_data.copy(), stable=True)
    print(result_stable)
    result_unstable = sort_numbers(sample_data.copy(), stable=False)
    print(result_unstable)

def sort_numbers(numbers: list[float], stable: bool = True) -> list[float]:
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list.")
    for item in numbers:
        if not isinstance(item, (int, float)):
            raise TypeError(f"All elements must be numeric, got {type(item).__name__}.")
    return sorted(numbers, key=lambda x: -x)
if __name__ == '__main__':
    sample_data = [3.5, 1.2, 4.8, 2.0, 3.9]
    result_stable = sort_numbers(sample_data.copy(), stable=True)
    result_unstable = sort_numbers(sample_data.copy(), stable=False)
    print("Original:", sample_data)
    print("Sorted (Stable):", result_stable)
    print("Sorted (Unstable):", result_unstable)

def stable_sort(numbers: list) -> list:
    return sorted(numbers)
def unstable_sort(numbers: list) -> list:
    numbers_copy = numbers.copy()
    if len(numbers_copy) > 1:
        for i in range(len(numbers_copy)):
            min_idx = i
            for j in range(i + 1, len(numbers_copy)):
                if numbers_copy[j] < numbers_copy[min_idx]:
                    min_idx = j
            if min_idx != i:
                numbers_copy[i], numbers_copy[min_idx] = numbers_copy[min_idx], numbers_copy[i]
    return numbers_copy
def create_sorter(stable: bool) -> callable:
    if stable:
        return stable_sort
    else:
        return unstable_sort
if __name__ == '__main__':
    sample_data = [5, 2, 8, 1, 9]
    sorted_stable = create_sorter(True)(sample_data)
    print(sorted_stable)
    sorted_unstable = create_sorter(False)(sample_data.copy())
    print(sorted_unstable)

from typing import Callable, List
def create_sorter(stable: bool = True) -> Callable[[List[float]], List[float]]:
    def sorter(numbers: List[float]) -> List[float]:
        return sorted(numbers, key=lambda x: -x if stable else 0.5 * (abs(x) + abs(-x)), reverse=not stable)
    return sorter
if __name__ == '__main__':
    sample_data = [3.14, 2.718, 1.618, 3.14]
    default_sorter = create_sorter()
    result_default = default_sorter(sample_data)
    unstable_sorter = create_sorter(stable=False)
    result_unstable = unstable_sorter(sample_data.copy())
    print(f"Default (Stable): {result_default}")
    print(f"Unstable:          {result_unstable}")

