import random
from datetime import datetime, timedelta
from collections import defaultdict
def generate_synthetic_data(num_records=100):
    data = []
    base_date = datetime.now() - timedelta(days=num_records)
    for i in range(num_records):
        timestamp = (base_date + timedelta(minutes=i)).isoformat()
        value_a = round(random.uniform(5, 25), 4)
        value_b = round(value_a * random.uniform(0.8, 1.2), 4)
        data.append({
            "id": i + 1,
            "timestamp": timestamp,
            "value_a": value_a,
            "value_b": value_b,
            "category": ["Alpha", "Beta"][i % 2]
        })
    return data
def perform_statistical_analysis(data):
    values = [row["value_a"] for row in data]
    categories = defaultdict(list)
    for item in data:
        cat_name = item["category"]
        val_b = item["value_b"]
        categories[cat_name].append(val_b)
    stats = {
        "mean_value_a": sum(values) / len(values),
        "std_deviation": (sum((x - sum(values)/len(values))**2 for x in values) / len(values)) ** 0.5,
        "min_value_a": min(values),
        "max_value_a": max(values),
    }
    category_stats = {}
    for cat_name, vals in categories.items():
        mean_cat = sum(vals) / len(vals)
        std_cat = (sum((x - mean_cat)**2 for x in vals) / len(vals)) ** 0.5
        category_stats[cat_name] = {"mean": round(mean_cat, 4), "std_deviation": round(std_cat, 4)}
    return stats, category_stats
if __name__ == '__main__':
    raw_data = generate_synthetic_data(120)
    global_stats, cat_stats = perform_statistical_analysis(raw_data)
    print(f"Global Mean: {global_stats['mean_value_a']:.4f}")
    print(f"Global Std Dev: {global_stats['std_deviation']:.4f}")
    for cat_name in ["Alpha", "Beta"]:
        if cat_name in cat_stats:
            s = cat_stats[cat_name]
            print(f"{cat_name} Mean: {s['mean']}")

import random
from datetime import datetime, timedelta
from collections import defaultdict
def generate_synthetic_data(num_records=100):
    data = []
    base_date = datetime.now() - timedelta(days=365)
    for i in range(num_records):
        timestamp = (base_date + timedelta(days=random.randint(0, 364))).isoformat()
        category = random.choice(['A', 'B', 'C'])
        value = round(random.gauss(100, 25), 2)
        flag = random.random() > 0.7
        data.append({
            "id": i + 1,
            "timestamp": timestamp,
            "category": category,
            "value": value,
            "flag": flag
        })
    return data
def analyze_data(data):
    categories = defaultdict(list)
    for item in data:
        categories[item["category"]].append(item["value"])
    stats = {}
    for cat_name, values in categories.items():
        mean_val = sum(values) / len(values)
        variance = sum((x - mean_val) ** 2 for x in values) / len(values) if len(values) > 0 else 0
        stats[cat_name] = {
            "count": len(values),
            "mean": round(mean_val, 4),
            "variance": round(variance, 4)
        }
    return data, stats
if __name__ == '__main__':
    raw_data = generate_synthetic_data(100)
    processed_data, analysis_results = analyze_data(raw_data)
    print(f"Total records: {len(processed_data)}")
    for cat_name in sorted(analysis_results.keys()):
        info = analysis_results[cat_name]
        print(f"{cat_name}: Count={info['count']}, Mean={info['mean']}, Variance={info['variance']}")

import sys
def optimize_sort_filter(data: list[int]) -> tuple[list[int], int]:
    if not data:
        return [], 0
    seen = set()
    filtered_unique = []
    for item in sorted(data):
        if item not in seen:
            seen.add(item)
            filtered_unique.append(item)
    return filtered_unique, len(seen)
if __name__ == '__main__':
    sample_data = [3, 1, 4, 1, 5, 9, 2, 6]
    result_list, unique_count = optimize_sort_filter(sample_data)
    print(f"Unique sorted count: {unique_count}")
    print("Filtered list:", result_list)

