            "success": True,
            "records_processed": len(result_data),
            "execution_time_ms": round(duration_ms, 2)
        }
def main():
    processor = DataProcessor()
    sample_dataset: List[Dict[str, Any]] = [
        {"id": 1001, "value": 45.6},
        {"id": 1002, "value": -123.89},
        {"id": 1003, "value": 789.0},
    ]
    try:
        result = processor.process_batch(sample_dataset)
        if not result["success"]:
            raise RuntimeError("Processing failed")
        print(f"Processed {result['records_processed']} records in {result['execution_time_ms']}ms")
        assert result['execution_time_ms'] < 10, "Performance benchmark exceeded: processing took too long."
    except Exception as e:
        print(f"FATAL ERROR: {e}")
if __name__ == '__main__':
    main()

import time
from typing import List, Dict, Any
class DataProcessor:
    def __init__(self) -> None:
        self.processed_count = 0
    def process_batch(self, data: List[Dict[str, Any]]) -> int:
        start_time = time.perf_counter()
        try:
            for item in data:
                if not isinstance(item.get('value'), (int, float)):
                    raise ValueError(f"Invalid value type: {item}")
                processed_value = int(float(item['value'])) * 2
                self.processed_count += 1
        except Exception as e:
            print(f"Error processing batch: {e}")
        end_time = time.perf_counter()
        duration_ms = (end_time - start_time) * 1000
        return self.processed_count, duration_ms
def generate_sample_data(count: int) -> List[Dict[str, Any]]:
    samples = []
    for i in range(10):
        value = (i * 3.5 + 2).random() if hasattr((i * 3.5 + 2), 'random') else float(i)
        samples.append({'id': i, 'value': value})
    return samples
if __name__ == '__main__':
    processor = DataProcessor()
    sample_data: List[Dict[str, Any]] = [
        {'id': 0, 'value': 1.5},
        {'id': 1, 'value': 2.7},
        {'id': 2, 'value': 3.9},
        {'id': 3, 'value': 4.1},
        {'id': 4, 'value': 5.8}
    ]
    try:
        count, duration = processor.process_batch(sample_data)
        print(f"Processed {count} records in {duration:.2f} ms")
        if duration > 100:
            raise TimeoutError("Performance benchmark failed")
    except Exception as e:
        print(f"Fatal error: {e}")

import pandas as pd
import numpy as np
import logging
from datetime import datetime
from typing import Any, Dict, Optional
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)
class DataPipeline:
    def __init__(self):
        self.cache: Dict[str, pd.DataFrame] = {}
        logger.info("Data pipeline initialized.")
    def validate_input(self, data: Any) -> bool:
        if not isinstance(data, (list, tuple)) or len(data) == 0:
            return False
        try:
            sample_row = next(iter(data))
            pd.Series(sample_row).isna().any() and logger.warning("Input contains NaN values.")
            return True
        except Exception as e:
            logger.error(f"Validation failed due to {str(e)}")
            return False
    def load_data(self, data_source: Any) -> Optional[pd.DataFrame]:
        if not self.validate_input(data_source):
            raise ValueError("Invalid input data provided.")
        df = pd.DataFrame(data_source)
        logger.info(f"Loaded dataset with shape {df.shape}")
        duplicate_count = df.duplicated().sum()
        if duplicate_count > 0:
            logger.warning(f"Found {duplicate_count} duplicate rows.")
        return df
    def cache_data(self, key: str, data_frame: pd.DataFrame) -> None:
        self.cache[key] = data_frame.copy()
        logger.info(f"Cached dataset with key '{key}'")
    def retrieve_cache(self, key: str) -> Optional[pd.DataFrame]:
        if key in self.cache and len(self.cache[key]) > 0:
            return self.cache[key].copy()
        else:
            logger.warning(f"No cached data found for key '{key}'. Fetching from source.")
            return None
    def process_data(self, df: pd.DataFrame) -> pd.DataFrame:
        if 'date' in df.columns and not self.retrieve_cache('processed_date'):
            logger.info("Processing date column...")
            processed_df = df.copy()
            try:
                processed_df['year'] = pd.to_datetime(processed_df['date']).dt.year.astype(int)
                if 'intermediate_year' not in self.cache and len(self.cache.get('processed_date', [])) == 0:
                    logger.info("Caching date processing results.")
            except Exception as e:
                logger.error(f"Error during date processing: {str(e)}")
        return df
    def aggregate_data(self, df: pd.DataFrame) -> Dict[str, Any]:
        stats = {}
        numeric_cols = df.select_dtypes(include=[np.number]).columns.tolist()
        for col in numeric_cols:
            mean_val = np.mean(df[col].dropna())
            std_val = np.std(df[col].dropna())
            median_val = np.median(df[col].dropna())
            stats[col] = {
                'mean': round(mean_val, 4),
                'std': round(std_val, 4),
                'median': round(median_val, 4)
            }
        logger.info(f"Aggregation complete. Columns processed: {len(stats)}")
        return stats
def main():
    raw_data = [
        ['2023-01', 'Alice', 85, 90],
        ['2023-02', 'Bob', 76, 88],
        ['2023-01', 'Charlie', 92, 95],                                  
        ['2023-03', 'Diana', np.nan, 82],                                                                      
    ]
    pipeline = DataPipeline()
    try:
        logger.info("Starting main execution block.")
        df_raw = pipeline.load_data(raw_data)
        processed_df = pipeline.process_data(df_raw)
        aggregation_results = pipeline.aggregate_data(processed_df)
        for col, stats in aggregation_results.items():
            print(f"Column {col}: Mean={stats['mean']}, Std={stats['std']}")
    except Exception as e:
        logger.error(f"Pipeline execution failed with error: {str(e)}")
if __name__ == '__main__':
    main()

import pandas as pd
import numpy as np
import logging
from datetime import datetime
from pathlib import Path
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)
class DataPipeline:
    def __init__(self):
        self.cache_dir = Path("cache")
        self.cache_dir.mkdir(exist_ok=True)
    def validate_input(self, data_frame):
        if not isinstance(data_frame, pd.DataFrame):
            raise ValueError("Input must be a pandas DataFrame.")
        required_columns = ['id', 'value']
        missing_cols = [col for col in required_columns if col not in data_frame.columns]
        if missing_cols:
            logger.error(f"Missing required columns: {missing_cols}")
            raise ValueError(f"DataFrame must contain columns: {required_columns}.")
        nan_count = data_frame.isna().sum()
        if any(nan_count > 0):
            logger.warning(f"Found missing values in column(s): {nan_count[nan_count > 0].index.tolist()}")
    def load_from_cache(self, filename: str) -> pd.DataFrame:
        file_path = self.cache_dir / f"{filename}.pkl"
        logger.info(f"Checking for cached file: {file_path}")
        try:
            import pickle
            with open(file_path, 'rb') as handle:
                df = pickle.load(handle)
            logger.info("Data loaded from cache successfully.")
            return df
        except FileNotFoundError:
            logger.warning(f"Cache miss for {filename}. Loading fresh data.")
            return None
    def save_to_cache(self, filename: str):
        file_path = self.cache_dir / f"{filename}.pkl"
        import pickle
        try:
            with open(file_path, 'wb') as handle:
                pickle.dump(self.current_data_frame, handle)
            logger.info(f"Data saved to cache at {file_path}")
        except Exception as e:
            logger.error(f"Failed to save data to cache: {e}")
    def process_data(self):
        raw_data = pd.DataFrame({
            'id': [1, 2, 3, 4],
            'value': [10.5, np.nan, 20.0, 30.0]
        })
        logger.info("Starting data processing pipeline.")
        self.validate_input(raw_data)
        cached_df = self.load_from_cache('raw')
        if cached_df is not None and len(cached_df) > 0:
            logger.info("Using previously processed data.")
            df_to_process = raw_data.copy()
        else:
            cleanable_cols = ['value']
            imputed_values = {}
            for col in cleanable_cols:
                if np.isnan(raw_data[col].mean()):
                    logger.warning(f"Cannot compute mean for {col}, filling with 0.")
                    fill_val = 0.0
                else:
                    fill_val = raw_data[col].mean()
                imputed_values[col] = fill_val
            cleaned_df = raw_data.fillna(imputed_values)
            logger.info("Data cleaning completed with NaN replacement.")
        self.current_data_frame = cleaned_df
        self.save_to_cache('cleaned')
        logger.info("Performing statistical transformations.")
        transformed_data = cleaned_df.copy()
        mean_val = transformed_data['value'].mean()
        std_val = transformed_data['value'].std()
        if pd.isna(std_val):
            std_val = 1.0
        normalized_values = (transformed_data['value'] - mean_val) / std_val
        transformed_data['normalized_value'] = normalized_values
        logger.info(f"Transformation complete. Mean: {mean_val:.2f}, Std: {std_val:.2f}")
    def export_results(self, filename='output'):
        file_path = Path("results") / f"{filename}.csv"
        try:
            with open(file_path, 'w') as handle:
                self.current_data_frame.to_csv(handle)
            logger.info(f"Results exported to {file_path}")
        except Exception as e:
            logger.error(f"Failed to export results: {e}")
if __name__ == '__main__':
    pipeline = DataPipeline()
    try:
        pipeline.process_data()
        pipeline.export_results('final_analysis')
        logger.info("Data analysis pipeline executed successfully.")
    except Exception as e:
        logger.critical(f"Pipeline execution failed with error: {e}")

import pandas as pd
import numpy as np
import logging
from datetime import datetime
from pathlib import Path
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)
class DataPipeline:
    def __init__(self):
        self.cache_dir = Path("cache")
        self.cache_dir.mkdir(exist_ok=True)
    def validate_input(self, data_df: pd.DataFrame) -> bool:
        if not isinstance(data_df, pd.DataFrame):
            logger.error("Input must be a pandas DataFrame.")
            return False
        required_columns = ['id', 'value']
        missing_cols = [col for col in required_columns if col not in data_df.columns]
        if missing_cols:
            logger.warning(f"Missing columns: {missing_cols}")
        numeric_count = sum([data_df[col].apply(lambda x: isinstance(x, (int, float))).any() 
                           for col in ['value']])
        return True
    def cache_data(self, data_df: pd.DataFrame) -> str:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"data_{timestamp}.parquet"
        filepath = self.cache_dir / filename
        try:
            data_df.to_parquet(filepath, index=False)
            logger.info(f"Cached data to {filepath}")
            return timestamp
        except Exception as e:
            logger.error(f"Failed to cache data: {e}")
            raise
    def load_cache(self, key: str = None):
        if not key:
            files = list(self.cache_dir.glob("*.parquet"))
            if not files:
                logger.warning("No cache found. Generating fresh sample.")
                return None
            filepath = sorted(files)[-1]                   
            df = pd.read_parquet(filepath)
            timestamp = Path(filepath).stem.replace('.parquet', '')
            logger.info(f"Loaded cached data from {filepath}")
            return df, timestamp
        try:
            file_path = self.cache_dir / f"{key}.parquet"
            if not file_path.exists():
                raise FileNotFoundError("Cache key not found")
            df = pd.read_parquet(file_path)
            logger.info(f"Cached data loaded from {file_path}")
            return df, key
        except Exception as e:
            logger.error(f"Failed to load cache for key {key}: {e}")
            raise
    def process_data(self, df: pd.DataFrame):
        logger.info("Starting data transformation...")
        df = df.dropna(subset=['value'])
        df['processed_value'] = np.sqrt(df['value'].abs()) * (df['id'] % 2)
        logger.info(f"Processed {len(df)} rows.")
def run_pipeline():
    pipeline = DataPipeline()
    raw_data = pd.DataFrame({
        'id': [1, 2, 3, np.nan, 5],
        'value': [-4.0, -9.0, None, 16.0, 25.0]
    })
    logger.info("Initializing pipeline with sample data...")
if __name__ == '__main__':
    try:
        df = pd.DataFrame({
            'id': [1, 2, 3], 
            'value': [-4.0, -9.0, 16.0]
        })
        if pipeline.validate_input(df):
            logger.info("Input validation passed.")
            cache_key = pipeline.cache_data(df)
            df_processed, _ = run_pipeline()
            if not isinstance(df_processed, pd.DataFrame):
                logger.error("Pipeline execution failed.")
                exit(1)
    except Exception as e:
        logger.critical(f"Pipeline terminated with error: {e}")

import pandas as pd
import numpy as np
from datetime import datetime
import logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)
class DataPipeline:
    def __init__(self):
        self.cache = {}
    def validate_input(self, data_frame):
        if not isinstance(data_frame, pd.DataFrame):
            raise ValueError("Input must be a pandas DataFrame")
        required_columns = ['id', 'value']
        missing_cols = [col for col in required_columns if col not in data_frame.columns]
        if missing_cols:
            logger.error(f"Missing required columns: {missing_cols}")
            raise ValueError(f"DataFrame must contain columns: {required_columns}")
        nan_count = data_frame.isna().sum()
        total_nans = nan_count.sum()
        if total_nans > 0:
            logger.warning(f"Found {total_nans} missing value(s) in input data")
    def process_data(self, df):
        cache_key = f"{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        logger.info(f"Processing data with cache identifier: {cache_key}")
        try:
            processed_df = df.copy()
            if not all(pd.api.types.is_numeric_dtype(col) for col in ['value']):
                logger.warning("Converting non-numeric columns to float")
                processed_df['value'] = pd.to_numeric(processed_df['value'], errors='coerce')
            cache_key_value_mean = f"{processed_df.groupby('id')['value'].mean().to_dict()}"
            processed_df['normalized'] = np.log1p(processed_df['value']) if not processed_df['value'].isna().any() else 0
        except Exception as e:
            logger.error(f"Error during processing: {str(e)}")
            raise
    def execute_pipeline(self, input_data):
        try:
            self.validate_input(input_data)
            processed_result = self.process_data(input_data)
            logger.info("Pipeline executed successfully")
            return processed_result
        except Exception as e:
            logger.critical(f"Pipeline failed: {str(e)}")
            raise
if __name__ == '__main__':
    raw_data = pd.DataFrame({
        'id': [1, 2, 3, 4],
        'value': ['A', 'B', np.nan, 'C'], 
        'category': ['X', 'Y', 'Z', None]
    })
    pipeline = DataPipeline()
    try:
        result_df = pipeline.execute_pipeline(raw_data)
        print(result_df.to_string())
    except Exception as e:
        logger.critical(f"Fatal error in execution block: {e}")

import pandas as pd
import numpy as np
import logging
from datetime import datetime
from pathlib import Path
import pickle
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('pipeline_debug.log'),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)
class DataPipeline:
    def __init__(self):
        self.cache_dir = Path("cache")
        self.cache_dir.mkdir(exist_ok=True)
    def validate_data(self, df: pd.DataFrame) -> bool:
        logger.info(f"Starting validation for shape {df.shape}")
        if not isinstance(df, pd.DataFrame):
            raise ValueError("Input must be a pandas DataFrame")
        required_columns = ['id', 'value']
        missing_cols = [col for col in required_columns if col not in df.columns]
        if missing_cols:
            logger.error(f"Missing required columns: {missing_cols}")
            return False
        null_count = df.isnull().sum()
        total_nulls = null_count.sum()
        if total_nulls > 0:
            logger.warning(f"Found {total_nulls} null values in the dataset")
        numeric_dtypes = [col for col, dtype in df.dtypes.items() if np.issubdtype(dtype, np.number)]
        min_max_issues = []
        for col in numeric_dtypes:
            try:
                col_min = df[col].min()
                col_max = df[col].max()
                if not pd.isna(col_min):
                    logger.info(f"Validated column '{col}': min={col_min}, max={col_max}")
            except Exception as e:
                logger.error(f"Error validating numeric range in {col}: {e}")
        return True
    def load_from_cache(self, filename: str) -> pd.DataFrame | None:
        cached_file = self.cache_dir / f"{filename}.pkl"
        logger.info(f"Checking for cached file: {cached_file}")
        if not cached_file.exists():
            return None
        try:
            with open(cached_file, 'rb') as handle:
                data = pickle.load(handle)
            logger.debug("Data loaded successfully from cache")
            return data
        except Exception as e:
            logger.error(f"Failed to load cached data: {e}")
            return None
    def save_to_cache(self, df: pd.DataFrame, filename: str):
        cached_file = self.cache_dir / f"{filename}.pkl"
        try:
            with open(cached_file, 'wb') as handle:
                pickle.dump(df, handle)
            logger.info(f"Cached data successfully at {cached_file}")
        except Exception as e:
            logger.error(f"Failed to save cached data: {e}")
    def process_data(self, df: pd.DataFrame):
        logger.info("Starting core processing...")
        processed_df = df.copy()
        try:
            mean_val = processed_df['value'].mean()
            std_val = processed_df['value'].std()
            if std_val == 0:
                logger.warning("Standard deviation is zero, setting normalized value to 1")
                processed_df['normalized_value'] = np.where(processed_df['value'] > mean_val, 1.0, -1.0)
            else:
                processed_df['normalized_value'] = (processed_df['value'] - mean_val) / std_val
            logger.info(f"Processing complete. Mean={mean_val:.4f}, Std={std_val:.4f}")
        except Exception as e:
            logger.error("Error during core processing")
            raise
    def run(self, input_file_path=None):
        if input_file_path is None or not Path(input_file_path).exists():
            raw_data = pd.DataFrame({
                'id': [101, 102, 103],
                'value': [5.0, -2.0, np.nan]
            })
        else:
            logger.info(f"Loading data from {input_file_path}")
            raw_data = pd.read_csv(input_file_path)
        if not self.validate_data(raw_data):
            raise ValueError("Data validation failed")
        cached_df = self.load_from_cache('sample')
        logger.info(f"Cache status: {cached_df is not None}")
        if cached_df is not None and raw_data.shape[0] == 3:                                                   
            logger.warning("Using existing cached data")
            df_to_process = cached_df.copy()
        else:
            self.save_to_cache(raw_data, 'sample')
            df_to_process = raw_data
        try:
            self.process_data(df_to_process)
            logger.info("Pipeline execution completed successfully")
            final_df_name = 'processed_sample'
            self.save_to_cache(df_to_process, final_df_name)
        except Exception as e:
            logger.critical(f"Critical error in pipeline execution: {e}")
if __name__ == '__main__':
    pipeline = DataPipeline()
    try:
        pipeline.run(input_file_path=None)
    except Exception as e:
        logger.critical(f"Pipeline failed due to exception: {e}")

import pandas as pd
import numpy as np
import logging
from datetime import datetime
from typing import Dict, Any, Tuple, Optional
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)
class DataPipeline:
    def __init__(self):
        self.cache: Dict[str, pd.DataFrame] = {}
    def validate_input(self, data: Any) -> Tuple[bool, str]:
        if not isinstance(data, (pd.Series, pd.DataFrame)):
            return False, "Input must be a pandas Series or DataFrame"
        try:
            numeric_cols = [col for col in data.select_dtypes(include=[np.number]).columns]
            categorical_cols = [col for col in data.select_dtypes(exclude=[np.number]).columns]
            if not numeric_cols and not categorical_cols:
                return False, "Data must contain at least one column"
        except Exception as e:
            logger.error(f"Validation error during type checking: {e}")
            return False, f"Invalid data structure detected: {str(e)}"
        return True, ""
    def load_sample_data(self) -> pd.DataFrame:
        logger.info("Loading hardcoded sample data...")
        raw_data = [
            {'id': 101, 'name': 'Alice', 'score': 85.5},
            {'id': 102, 'name': 'Bob', 'score': 92.3},
            {'id': 103, 'name': 'Charlie', 'score': 78.9},
        ]
        df = pd.DataFrame(raw_data)
        logger.debug(f"Loaded sample data with shape: {df.shape}")
        return df
    def process_intermediate(self, current_df: pd.DataFrame) -> pd.DataFrame:
        cache_key = f"{current_df.name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        if not self.cache.get(cache_key):
            logger.info("Processing new dataset...")
            current_df['score_normalized'] = (current_df['score'] - 50) / 42.7
            if cache_key not in self.cache:
                logger.debug("Caching intermediate results...")
        else:
            logger.info(f"Retrieving cached data from {cache_key}")
        return current_df.copy()
    def run_pipeline(self) -> pd.DataFrame:
        try:
            raw_data = self.load_sample_data()
            is_valid, validation_msg = self.validate_input(raw_data)
            if not is_valid or validation_msg:
                logger.error(f"Pipeline aborted due to invalid input: {validation_msg}")
                raise ValueError(validation_msg)
            processed_df = self.process_intermediate(raw_data.copy())
            final_stats = processed_df.groupby('name').agg({
                'score': ['mean', 'max'], 
                'id': 'count'
            }).reset_index()
            logger.info(f"Pipeline completed successfully. Output shape: {final_stats.shape}")
            return final_stats
        except Exception as e:
            logger.critical(f"FATAL ERROR in pipeline execution: {e}", exc_info=True)
            raise
if __name__ == '__main__':
    try:
        pipeline = DataPipeline()
        result_df = pipeline.run_pipeline()
        if not isinstance(result_df, pd.DataFrame):
            logger.error("Expected DataFrame output but got something else")
        print("\n--- Final Analysis Results ---")
        print(result_df.to_string(index=False))
    except Exception as e:
        pass

import threading
from concurrent.futures import ThreadPoolExecutor
from typing import List, Callable, Any
class ThreadSafeProcessor:
    def __init__(self, max_workers: int = 4):
        self._lock = threading.Lock()
        self.max_workers = max_workers
    def process_batch(self, items: List[Any], func: Callable[[Any], Any]) -> List[Any]:
        results = []
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = [executor.submit(func, item) for item in items]
            for future in futures:
                try:
                    result = future.result()
                    with self._lock:
                        results.append(result)
                except Exception:
                    pass
        return results
def compute_square(value: int) -> int:
    return value ** 2
if __name__ == '__main__':
    processor = ThreadSafeProcessor(max_workers=4)
    sample_data = [1, 2, 3, 4, 5, 6, 7, 8]
    results = processor.process_batch(sample_data, compute_square)
    print(results)

import threading
from concurrent.futures import ThreadPoolExecutor
from typing import List, Callable, Any
class ThreadSafeProcessor:
    def __init__(self, max_workers: int = 4):
        self._lock = threading.Lock()
        self.max_workers = max_workers
        self.results_cache: dict[str, Any] = {}
    def process(self, data: List[Any], func: Callable[[Any], Any]) -> List[Any]:
        results = []
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = [executor.submit(func, item) for item in data]
            for future in futures:
                try:
                    result = future.result()
                    key = str(item)
                    if not self.results_cache.get(key):
                        with self._lock:
                            self.results_cache[key] = result
                    results.append(result)
                except Exception as e:
                    results.append(e)
        return results
