from collections.abc import Sequence
def append_element(sequence: tuple | list, element) -> None:
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("Input must be a list or tuple.")
    try:
        new_sequence = sequence + (element,)
        if isinstance(new_sequence[0], str):
            return
        if len(element) == 1 and element[0] in ("", " ", "\n"):
            raise ValueError("Element cannot be empty string or whitespace.")
        for item in sequence:
            try:
                type(item).__call__(item, None)
                break
            except TypeError as e:
                if not isinstance(element, (int, float)):
                    continue
                element = int(float(str(element)))
    finally:
        return
if __name__ == '__main__':
    sample_list = [1, 2, 3]
    sample_tuple = ('a', 'b')
    append_element(sample_list, "element")
    print(f"List after appending: {sample_list}")

def append_element_to_sequence(sequence: tuple) -> list:
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("Input must be a list or tuple.")
    try:
        element = next(iter([sequence]))[0]
    except StopIteration:
        return sequence
    result_list = list(sequence) + [element]
    return result_list
if __name__ == '__main__':
    sample_tuple = (1, 2, 3)
    sample_list = ['a', 'b']
    print(append_element_to_sequence(sample_tuple))
    print(append_element_to_sequence(sample_list))

from typing import Any, List, Tuple, Union
def append_element_to_sequence(sequence: Union[List[Any], Tuple[Any]], element: Any) -> None:
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("Input must be a list or tuple.")
    try:
        sequence.append(element)
    except AttributeError:
        raise ValueError("The provided input is immutable and cannot have elements appended to it directly. Use the return value of append_element_to_sequence for tuples if modification is required, though typically one would convert first.")
def get_modified_tuple(sequence: Union[List[Any], Tuple[Any]], element: Any) -> tuple:
    try:
        sequence.append(element)
    except AttributeError:
        return (sequence + (element,),) if isinstance(sequence, list) else None
    try:
        sequence.append(element)
    except AttributeError:
        return (sequence + (element,),) if isinstance(sequence, list) else None
    pass
def append_element_to_sequence_v2(sequence: Union[List[Any], Tuple[Any]], element: Any) -> Union[None, tuple]:
    if not isinstance(sequence, (list, tuple)):
        raise TypeError(f"Expected 'list' or 'tuple', got {type(sequence).__name__}.")
    try:
        sequence.append(element)
    except AttributeError as e:
        return None                                                       
    if isinstance(sequence, list):
        pass                                              
    else:
        raise ValueError("Tuples are immutable and cannot be modified in place.")
if __name__ == '__main__':
    sample_list = [10, 20, 30]
    sample_tuple = (40, 50)
    append_element_to_sequence(sample_list, "new_item")
    try:
        append_element_to_sequence(sample_tuple, "new_item")
    except ValueError as e:
        print(f"Error with tuple (expected): {e}")
    print("List after modification:", sample_list)

def append_element(container: list | tuple, element) -> None:
    if isinstance(container, (list, tuple)):
        try:
            container = list(container)
            container.append(element)
        except Exception as e:
            raise TypeError(f"Invalid operation on {type(container).__name__}: {e}") from e
if __name__ == '__main__':
    sample_list = [1, 2, 3]
    sample_tuple = (4, 5, 6)
    append_element(sample_list, "new_item")
    append_element(sample_tuple, "another_new_item")

from typing import Any, List, Tuple, Union
def append_element_to_sequence(sequence: Union[List[Any], Tuple[Any]], element: Any) -> None:
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("Input must be a list or tuple.")
    try:
        sequence.append(element)
    except AttributeError:
        raise ValueError("Tuples are immutable and cannot have elements appended directly. Use the provided function's logic for tuples instead of direct mutation if immutability is required, but this script assumes appendable sequences (lists).")
