    manager.add_item("Widget")
    manager.add_item("Gadget")
    print(manager.get_all_items())

from abc import ABC, abstractmethod
class ItemNameManager(ABC):
    @abstractmethod
    def get_name(self) -> str:
        pass
    @abstractmethod
    def set_name(self, name: str) -> None:
