    manager = InventoryManager()
    sample_data = [
        ("Apple", "10"),
        ("Banana", "5"),
        ("Orange", "3")
    ]
    for item, qty in sample_data:
        try:
            manager.add_item(item, qty)
        except ValueError as e:
            print(f"Error adding {item}: {e}")
    total = manager.get_total_items()
    print(f"Total items in inventory: {total}")

