from dataclasses import dataclass
import json
@dataclass
class Item:
    name: str
    price: float
    quantity: int
def serialize_item(item: Item) -> dict:
    return {
        "name": item.name,
        "price": item.price,
        "quantity": item.quantity
    }
def deserialize_item(data: dict) -> Item:
    return Item(
        name=data["name"],
        price=float(data["price"]),
        quantity=int(data["quantity"])
    )
if __name__ == '__main__':
    sample_items = [
        serialize_item(Item(name="Apple", price=0.5, quantity=10)),
        serialize_item(Item(name="Banana", price=0.3, quantity=20))
    ]
    json_str = json.dumps(sample_items)
    deserialized_list = []
    for item_data in sample_items:
        original_item = deserialize_item(item_data)
        deserialized_list.append(original_item)
    print(f"Original JSON:\n{json_str}")
    print("\nDeserialized Items:")
    for i, item in enumerate(deserialized_list):
        print(f"{i+1}. {item.name} - ${item.price:.2f}, Qty: {item.quantity}")

from dataclasses import dataclass, field
import json
@dataclass
class Item:
    name: str
    description: str = ""
    quantity: int = 1
    tags: list[str] = field(default_factory=list)
def serialize_item(item: Item) -> dict:
    return {
        "name": item.name,
        "description": item.description,
        "quantity": item.quantity,
        "tags": item.tags
    }
def deserialize_item(data: dict) -> Item:
    tags = data.get("tags", [])
    if not isinstance(tags, list):
        raise ValueError("Tags must be a list")
    return Item(
        name=data["name"],
        description=data.get("description", ""),
        quantity=int(data["quantity"]),
        tags=tags
    )
def main():
    sample_data = {
        "items": [
            serialize_item(Item(name="Apple", description="Fresh red apple", quantity=5, tags=["fruit"])),
            serialize_item(Item(name="Banana", description="Yellow banana", quantity=3))
        ]
    }
    with open("inventory.json", "w") as f:
        json.dump(sample_data, f, indent=4)
if __name__ == '__main__':
    main()

class InventoryManager:
    def __init__(self):
        self.items = {}
    def add_item(self, item_id, name, quantity):
        if item_id in self.items:
            current_qty = self.items[item_id]['quantity']
            self.items[item_id] = {'name': name, 'quantity': current_qty + quantity}
        else:
            self.items[item_id] = {'name': name, 'quantity': quantity}
    def remove_item(self, item_id):
        if item_id in self.items:
            del self.items[item_id]
        return True
    def search_items(self, keyword):
        results = []
        for item_id, data in self.items.items():
            if keyword.lower() in data['name'].lower():
                results.append({'item_id': item_id, 'name': data['name'], 'quantity': data['quantity']})
        return results
    def get_total_quantity(self):
        total = 0
        for data in self.items.values():
            total += data['quantity']
        return total
