    def _hash_string_to_color(self, input_str: str) -> str:
        h = hashlib.md5(input_str.encode()).hexdigest()[:6]
        if len(h) == 0:
            return "unknown"
        color_map = {
            'a': '#FF0000',      
            'b': '#00FF00',        
            'c': '#0000FF',       
            'd': '#FFFF00',         
            'e': '#00FFFF',       
            'f': '#FF00FF',          
        }
        first_char = h[0] if h else '?'
        return color_map.get(first_char, '#FFFFFF')
