        'Citrus': [],
        'Berry': [],
        'Tropical': []
    }
    for fruit in fruits_list:
        if any(word.lower() in fruit.lower() for word in ['orange', 'lemon', 'lime']):
            categories['Citrus'].append(fruit)
        elif any(word.lower() in fruit.lower() for word in ['strawberry', 'blueberry', 'raspberry']):
            categories['Berry'].append(fruit)
        else:
            categories['Tropical'].append(fruit)
    return categories
if __name__ == '__main__':
    sample_input = "apple, orange, banana, strawberry, mango, lemon"
    fruits = parse_fruit_input(sample_input)
    grouped = categorize_fruits(fruits)
    for category_name, items in grouped.items():
        print(f"{category_name}: {', '.join(items)}")

def parse_fruit_input(input_string):
    return [fruit.strip().lower() for fruit in input_string.split(',') if fruit.strip()]
def categorize_fruits(fruits_list, classification_rules):
    categorized = {}
    def apply_rule(rule_name, rule_func):
        return {rule_name: [fruit for fruit in fruits_list if rule_func(fruit)]}
    has_seed = lambda f: 'seed' in f
    categorized['citrus_with_seeds'] = apply_rule('Citrus with Seeds', has_seed)
    categorized['red_fruits'] = apply_rule('Red Fruits', lambda f: f.startswith(('apple', 'strawberry')))
    return categorized
def main():
    raw_input = "Apple, Banana, Orange, Strawberry, Watermelon, Grape"
    fruits = parse_fruit_input(raw_input)
    groups = categorize_fruits(fruits, {})                                                                           
    print("Fruit Groups:")
    for category_name, group_items in sorted(groups.items()):
        if group_items:
            print(f"{category_name}: {', '.join(group_items)}")
if __name__ == '__main__':
    main()

def parse_fruit_input(input_string):
    return [fruit.strip() for fruit in input_string.split(',') if fruit.strip()]
def categorize_fruits(fruits_list, classification_rules):
    categorized = {}
    def get_category(fruit_name):
        name_lower = fruit_name.lower()
        if 'red' in name_lower or 'apple' == name_lower:
            return 'Red Fruits'
        elif 'green' in name_lower or 'lime' == name_lower:
            return 'Green Fruits'
        else:
            return 'Other Fruits'
    for fruit in fruits_list:
        category = get_category(fruit)
        if category not in categorized:
            categorized[category] = []
        categorized[category].append(fruit)
    return categorized
def main():
    raw_input = "apple, banana, orange, strawberry, lime"
    fruits = parse_fruit_input(raw_input)
    groups = categorize_fruits(fruits, {})
    for category, fruit_list in groups.items():
        print(category + ":")
        for item in fruit_list:
            print("- " + item)
if __name__ == '__main__':
    main()

import json
import logging
from collections import defaultdict
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
def is_valid_record(record):
    if not isinstance(record, dict):
        return False
    required_fields = ['type', 'quantity']
    for field in required_fields:
        if field not in record or not isinstance(record[field], (int, float)):
            return False
    return True
def process_fruits(json_input):
    logger.info("Starting fruit processing")
    valid_entries = []
    try:
        data = json.loads(json_input)
    except json.JSONDecodeError as e:
        logger.error(f"JSON parsing failed: {e}")
        raise
    if not isinstance(data, list):
        logger.warning("Input is not a JSON array")
        return []
    for index, record in enumerate(data):
        logger.info(f"Processing record at index {index}: {record.get('type', 'unknown')}")
        if is_valid_record(record):
            valid_entries.append(record)
            logger.debug(f"Record added to valid list: type={record['type']}, quantity={record['quantity']}")
        else:
            logger.warning(f"Skipping invalid record at index {index}: missing or incorrect fields")
    grouped = defaultdict(list)
    for entry in valid_entries:
        fruit_type = str(entry.get('type', 'unknown'))
        grouped[fruit_type].append({
            "quantity": int(entry['quantity']),
            "name": entry.get('name', '')
        })
    logger.info(f"Processing complete. Found {len(grouped)} unique types.")
    return dict(grouped)
if __name__ == '__main__':
    sample_data = [
        {"type": "apple", "quantity": 5, "name": "Red Apple"},
        {"type": "banana", "quantity": 3},
        {"type": "orange", "quantity": -2},
        {"type": "grape", "quantity": 10, "name": "Green Grape"},
        {"missing_field": True},
        {"type": "pear"}
    ]
    json_str = json.dumps(sample_data)
    try:
        result = process_fruits(json_str)
        logger.info("Output generation started")
        for fruit_type, entries in sorted(result.items()):
            total_qty = sum(e['quantity'] for e in entries)
            names = [e['name'] if 'name' in e else '' for e in entries]
            output_line = f"{fruit_type}: {len(entries)} items (Total Qty: {total_qty}) - Names: {'; '.join(names)}"
            logger.info(output_line)
    except Exception as e:
        logger.critical(f"Unexpected error during processing: {e}")

import json
import logging
from collections import defaultdict
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
def is_valid_entry(entry):
    if not isinstance(entry, dict):
        return False
    required_fields = ['type', 'quantity']
    for field in required_fields:
        if field not in entry or entry[field] == '' or entry[field] is None:
            logger.warning(f"Invalid entry missing or empty {field}: {entry}")
            return False
    try:
        int(entry['quantity'])
    except ValueError:
        logger.error(f"Entry has invalid quantity type for key 'type': {entry.get('type')}")
        return False
    if not isinstance(entry['type'], str):
        logger.warning("Invalid entry with non-string type field.")
        return False
    return True
def process_fruits(data):
    valid_entries = []
    invalid_count = 0
    for idx, item in enumerate(data.get('records', [])):
        if is_valid_entry(item):
            valid_entries.append(item)
        else:
            logger.warning(f"Skipping record at index {idx} due to validation failure.")
            invalid_count += 1
    return {'valid': valid_entries, 'invalid_skipped': invalid_count}
def group_by_type(entries):
    grouped = defaultdict(list)
    for entry in entries:
        fruit_type = str(entry['type']).lower()
        grouped[fruit_type].append({
            'quantity': int(entry['quantity']),
            'original_entry': entry
        })
    result_dict = {}
    for key, value_list in sorted(grouped.items()):
        total_quantity = sum(item['quantity'] for item in value_list)
        count = len(value_list)
        result_dict[key] = {'total_count': count, 'sum_of_quantities': total_quantity}
    return dict(result_dict)
if __name__ == '__main__':
    sample_data = {
        "records": [
            {"type": "apple", "quantity": 10},
            {"type": "banana", "quantity": ""},
            {"type": "orange"},
            {"type": "grape", "quantity": -5},
            {"type": "mango", "quantity": "twenty"},
        ]
    }
    logger.info("Starting fruit record processing.")
    try:
        processed = process_fruits(sample_data)
        grouped_results = group_by_type(processed['valid'])
        logger.info(f"Processing complete. Valid records found: {len(processed['valid'])}. Invalid skipped: {processed['invalid_skipped']}.")
        for fruit, stats in grouped_results.items():
            logger.info(f"Fruit type '{fruit}': Count={stats['total_count']}, Total Quantity={stats['sum_of_quantities']}")
    except Exception as e:
        logger.exception("An unexpected error occurred during processing.")

import json
import logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
def validate_entry(entry):
    if not isinstance(entry, dict):
        return False
    required_fields = ['type', 'quantity']
    for field in required_fields:
        if field not in entry or not isinstance(entry[field], (int, float)):
            return False
    valid_types = {'apple', 'banana', 'cherry'}
    if entry['type'].lower() not in valid_types:
        return False
    return True
def process_fruits(data):
    logger.info("Starting fruit data processing.")
    try:
        parsed_data = json.loads(data)
    except json.JSONDecodeError as e:
        logger.error(f"JSON parsing failed: {e}")
        raise
    grouped_results = {}
    if isinstance(parsed_data, list):
        for item in parsed_data:
            if validate_entry(item):
                fruit_type = item['type'].lower()
                quantity = int(item['quantity'])
                logger.debug(f"Validated entry: {fruit_type}, qty={quantity}")
                grouped_results.setdefault(fruit_type, []).append(quantity)
    elif isinstance(parsed_data, dict):
        for key, value in parsed_data.items():
            if validate_entry(value):
                fruit_type = value['type'].lower()
                quantity = int(value['quantity'])
                logger.debug(f"Validated entry: {fruit_type}, qty={quantity}")
                grouped_results.setdefault(fruit_type, []).append(quantity)
    else:
        raise ValueError("Input must be a list or dictionary of entries.")
    return grouped_results
if __name__ == '__main__':
    sample_data = [
        {"type": "apple", "quantity": 10},
        {"type": "Banana", "quantity": 5.5},
        {"type": "cherry"},
        {"missing_type": True, "quantity": 3},
        {"type": "grape", "quantity": 2}
    ]
    input_json = json.dumps(sample_data)
    try:
        result = process_fruits(input_json)
        logger.info("Processing completed successfully.")
        print(json.dumps(result))
    except Exception as e:
        logger.error(f"Unexpected error occurred: {e}")

import json
import logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
def is_valid_entry(entry):
    if not isinstance(entry, dict):
        return False
    required_fields = ['type', 'quantity']
    for field in required_fields:
        if field not in entry or entry[field] == "":
            return False
    try:
        int(entry['quantity'])
    except ValueError:
        return False
    return True
def process_fruits(data):
    logger.info("Starting fruit data processing")
    valid_entries = []
    if not isinstance(data, list):
        logger.error("Input must be a JSON array of records")
        return {}
    for idx, entry in enumerate(data):
        logger.debug(f"Processing record {idx}")
        if is_valid_entry(entry):
            fruit_type = entry['type']
            quantity = int(entry['quantity'])
            valid_entries.append({'type': fruit_type, 'quantity': quantity})
            current_count = sum(e['quantity'] for e in valid_entries if e['type'] == fruit_type)
            logger.info(f"Added {fruit_type} with total count: {current_count}")
        else:
            logger.warning(f"Ignoring invalid record at index {idx}: {entry}")
    grouped = {}
    for entry in valid_entries:
        t = entry['type']
        if t not in grouped:
            grouped[t] = 0
        grouped[t] += entry['quantity']
    logger.info("Processing completed successfully")
    return grouped
if __name__ == '__main__':
    sample_data = [
        {"type": "apple", "quantity": "5"},
        {"type": "banana", "quantity": ""},
        {"type": "orange", "quantity": 3.0},
        {"type": "grape", "quantity": "12"}
    ]
    result = process_fruits(sample_data)
    logger.info(f"Final grouped data: {result}")

