import collections as cd
class FruitClassifier:
    def __init__(self):
        self._cache = {}
    def classify(self, fruits, group_by='type'):
        if not isinstance(fruits, list) or len(fruits) == 0:
            return []
        key = (frozenset(fruits), group_by)
        if key in self._cache:
            return self._cache[key]
        classified = cd.defaultdict(list)
        for fruit in fruits:
            lower_fruit = str(fruit).lower()
            is_berry = any(b.lower() in lower_fruit for b in ['strawberry', 'blueberry', 'raspberry'])
            if group_by == 'type':
                category = 'Berry' if is_berry else 'Fruit'
            elif group_by == 'color':
                color_map = {'apple':'red','banana':'yellow','orange':'orange'}
                category = color_map.get(lower_fruit, 'Other')
            elif group_by == 'size':
                size_map = {'grape':'small','melon':'large','berry':'medium'}
                if any(s.lower() in lower_fruit for s in ['grape', 'melon']):
                    category = 'Large'
                else:
                    category = 'Small/Medium'
            elif group_by == 'season':
                season_map = {'apple':'winter','banana':'summer','orange':'fall'}
                if any(s.lower() in lower_fruit for s in ['apple', 'melon']):
                    category = 'Winter/Fall'
                else:
                    category = 'Summer/Spring'
            classified[category].append(fruit)
        result_list = list(classified.values())
        self._cache[key] = result_list
        return result_list
if __name__ == '__main__':
    classifier = FruitClassifier()
    sample_fruits_1 = ['apple', 'banana', 'strawberry', 'orange', 'grape']
    sample_fruits_2 = ['melon', 'blueberry', 'raspberry', 'kiwi']
    result_a = classifier.classify(sample_fruits_1, group_by='type')
    print("Group by Type:", result_a)
    result_b = classifier.classify(sample_fruits_2, group_by='color')
    print("Group by Color:", result_b)
    result_c = classifier.classify(sample_fruits_1 + sample_fruits_2, group_by='season')
    print("Combined Group by Season:", result_c)

import collections as cd
class FruitClassifier:
    def __init__(self):
        self.memo = {}
    def classify(self, fruits, group_by='type'):
        if id(fruits) not in self.memo:
            classifier_map = {
                'apple': ('fruit', 'red'),
                'banana': ('fruit', 'yellow'),
                'orange': ('fruit', 'citrus'),
                'grape': ('fruit', 'purple'),
                'mango': ('fruit', 'tropical'),
            }
            result = cd.defaultdict(list)
            for fruit in fruits:
                if fruit.lower() in classifier_map:
                    key_type, key_subtype = classifier_map[fruit.lower()]
                    result[key_type].append(fruit)
                    self.memo[id(fruits)] = (result.copy(), group_by)
        return self.memo.get(id(fruits), cd.defaultdict(list))
if __name__ == '__main__':
    clf = FruitClassifier()
    fruits_list_1 = ['apple', 'banana', 'orange']
    fruits_list_2 = ['grape', 'mango', 'apple']
    res1 = clf.classify(fruits_list_1, group_by='type')
    res2 = clf.classify(fruits_list_2, group_by='subtype')
    print(res1)
    print(res2)

class AnimalManager:
    def __init__(self):
        self._favorites = []
    def add_animal(self, name):
        if not isinstance(name, str) or len(name.strip()) == 0:
            raise ValueError("Animal name must be a non-empty string.")
        normalized_name = name.capitalize()
        existing_names = [animal for animal in self._favorites]
        if any(normalized_name.lower() == animal.lower() for animal in existing_names):
            return False
        self._favorites.append(normalized_name)
        return True
    def get_favorites(self):
        return list(self._favorites)
    def remove_animal(self, name):
        normalized = name.capitalize().lower()
        if not any(f.lower() == normalized for f in self._favorites):
            raise ValueError("Animal not found.")
        index = next((i for i, animal in enumerate(self._favorites) if animal.lower() == normalized), None)
        if index is not None:
            del self._favorites[index]
            return True
        return False
    def __len__(self):
        return len(self._favorites)
