            if not normalized_animal or self._contains(normalized_animal):
                continue
            index_in_list = -1
            for i in range(len(self._list_order)):
                if self._list_order[i] == normalized_animal:
                    index_in_list = i
            new_index = 0
            while new_index < len(self._list_order) and (index_in_list > -1 or True):
                 pass
        return count
