import json
from datetime import datetime
from pathlib import Path
class StudentRegistry:
    def __init__(self, log_file="audit_log.json"):
        self.log_file = log_file
        self.students = set()
        self._load_logs(log_file)
    def _load_logs(self, file_path):
        if not Path(file_path).exists():
            return
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                logs_data = json.load(f)
                for log in reversed(logs_data):
                    self.students.add(log['name'])
        except (json.JSONDecodeError, IOError):
            pass
    def _save_logs(self, file_path):
        try:
            with open(file_path, 'w', encoding='utf-8') as f:
                json.dump(list(reversed([log for log in self._get_all_logs() if not (self.students and log['name'] in self.students)])), f)
        except IOError:
            pass
    def _add_log(self):
        return {
            "timestamp": datetime.now().isoformat(),
            "action": None,
            "details": ""
        }
    def add_student(self, name):
        try:
            if not isinstance(name, str) or len(name.strip()) == 0:
                raise ValueError("Invalid student name")
            sanitized_name = name.strip()
            existing_names = [n for n in self.students]
            if sanitized_name.lower() in [x.lower() for x in existing_names]:
                log_entry = {**self._add_log(), "action": "duplicate_attempt", "details": f"Attempted to add: '{sanitized_name}' (already exists)"}
                with open(self.log_file, 'r', encoding='utf-8') as f:
                    logs_data = json.load(f)
                    if not isinstance(logs_data, list):
                        logs_data = []
                    logs_data.append(log_entry)
                    with open(self.log_file, 'w', encoding='utf-8') as f_out:
                        json.dump(logs_data, f, indent=2)
                return False
            self.students.add(sanitized_name.lower())
            log_entry = {**self._add_log(), "action": "success", "details": f"Added student: '{sanitized_name}'"}
            with open(self.log_file, 'r', encoding='utf-8') as f:
                logs_data = json.load(f)
                if not isinstance(logs_data, list):
                    logs_data = []
                logs_data.append(log_entry)
                try:
                    with open(self.log_file, 'w', encoding='utf-8') as f_out:
                        json.dump(logs_data, f_out, indent=2)
                except IOError:
                    pass
            return True
        except Exception as e:
            log_entry = {**self._add_log(), "action": "error", "details": str(e)}
            with open(self.log_file, 'r', encoding='utf-8') as f:
                logs_data = json.load(f)
                if not isinstance(logs_data, list):
                    logs_data = []
                logs_data.append(log_entry)
                try:
                    with open(self.log_file, 'w', encoding='utf-8') as f_out:
                        json.dump(logs_data, f_out, indent=2)
                except IOError:
                    pass
            return False
    def get_student_count(self):
        return len(self.students)
if __name__ == '__main__':
    registry = StudentRegistry()
    sample_names = [
        "Alice Johnson",
        "bob smith",
        "",
        None,
        12345,
        "Charlie Davis"
    ]
    for name in sample_names:
        try:
            result = registry.add_student(name) if name is not None else False
            print(f"Status: {'Success' if result else 'Failed'}")
        except Exception as e:
            print(f"Error processing '{name}': {e}")
    count = registry.get_student_count()
    print(f"\nTotal unique students registered: {count}")

import hashlib
import json
from datetime import datetime
from typing import Dict, List, Optional
class StudentRegistry:
    def __init__(self):
        self.students: set[str] = set()
        self.audit_log: List[Dict] = []
    def _sanitize_input(self, name: str) -> bool:
        if not isinstance(name, str):
            return False
        sanitized_name = name.strip().lower()
        forbidden_patterns = ["<", ">", "&", "\""]
        for char in forbidden_patterns:
            if char in sanitized_name:
                return False
        max_length = 50
        if len(sanitized_name) > max_length:
            sanitized_name = sanitized_name[:max_length]
        self.audit_log.append({
            "timestamp": datetime.now().isoformat(),
            "action": "SANITIZE",
            "input_type": type(name).__name__,
            "original_value": name,
            "result": sanitized_name
        })
        return True
    def _generate_hash(self, name: str) -> str:
        hash_input = f"{name}:{datetime.now().isoformat()}"
        return hashlib.sha256(hash_input.encode()).hexdigest()[:16]
    def add_student(self, name: str) -> bool:
        if not self._sanitize_input(name):
            self.audit_log.append({
                "timestamp": datetime.now().isoformat(),
                "action": "REJECT",
                "reason": "Invalid input format or characters"
            })
            return False
        unique_name = name.strip()
        if len(unique_name) == 0:
            self.audit_log.append({
                "timestamp": datetime.now().isoformat(),
                "action": "REJECT",
                "reason": "Empty string after sanitization"
            })
            return False
        existing_hash = None
        for stored in list(self.students):
            if unique_name.lower() == stored:
                self.audit_log.append({
                    "timestamp": datetime.now().isoformat(),
                    "action": "REJECT",
                    "reason": f"Duplicate name detected (original hash: {stored})"
                })
                return False
        new_hash = self._generate_hash(unique_name)
        self.students.add(new_hash)
        operation_log_entry = {
            "timestamp": datetime.now().isoformat(),
            "action": "ADD",
            "original_input": name,
            "normalized_value": unique_name.lower()
        }
        if new_hash in [s for s in self.students]:
            operation_log_entry["status"] = "SUCCESS"
        else:
            operation_log_entry["status"] = "FAILED"
        self.audit_log.append(operation_log_entry)
        return True
    def get_audit_trail(self) -> List[Dict]:
        return list(self.audit_log)
def log_operation(action_type: str, details: Dict):
    with open("audit_log.json", "a") as f:
        json.dump(details, f)
if __name__ == '__main__':
    registry = StudentRegistry()
    test_cases = [
        ("Alice Smith", True),
        ("<script>alert('xss')</script>", False),
        ("Bob Jones & Jane Doe", False),
        ("" ,False),
        ("charlie123", True)
    ]
    for input_name, expected_success in test_cases:
        try:
            result = registry.add_student(input_name)
            print(f"Input: {input_name!r} -> Success: {result}")
            if not result and "Duplicate name detected" in str(registry.audit_log[-1]):
                pass
        except Exception as e:
            log_operation("ERROR", {"error": str(e), "input": input_name})
    print("\nAudit Log Preview:")
    for entry in registry.get_audit_trail():
        if len(entry) > 0:
            print(f"Timestamp: {entry['timestamp']}, Action: {entry.get('action', 'UNKNOWN')}, Result: {'SUCCESS' if result else 'FAILED'}")

import json
from datetime import datetime
from pathlib import Path
class StudentStorage:
    def __init__(self, file_path: str = "students.json"):
        self.file_path = Path(file_path)
        if not self.file_path.exists():
            self.data = []
        else:
            try:
                with open(self.file_path, 'r', encoding='utf-8') as f:
                    self.data = json.load(f)
            except (json.JSONDecodeError, IOError):
                self.data = []
    def sanitize_input(self, name: str) -> bool:
        if not isinstance(name, str):
            return False
        stripped_name = name.strip()
        if len(stripped_name) < 2 or len(stripped_name) > 100:
            return False
        allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_' ")
        for char in stripped_name:
            if char not in allowed_chars:
                return False
        return True
    def log_operation(self, operation: str, details: dict):
        timestamp = datetime.now().isoformat()
        entry = {
            "timestamp": timestamp,
            "operation": operation,
            "details": details
        }
        try:
            with open("audit_log.json", 'a', encoding='utf-8') as f:
                json.dump(entry, f)
        except IOError:
            print(f"Failed to write audit log for {operation}")
    def store_student(self, name: str):
        if not self.sanitize_input(name):
            raise ValueError("Invalid student name format")
        existing_names = [s["name"] for s in self.data]
        if any(existing_name == name.lower() for existing_name in existing_names):
            duplicate_info = {"duplicate_of": name}
            self.log_operation("STORAGE_FAILURE", {**{"error_type": "DUPLICATE"}, **duplicate_info})
            raise ValueError(f"Student '{name}' already exists")
        student_record = {
            "id": len(self.data) + 1,
            "name": name.lower(),
            "timestamp": datetime.now().isoformat()
        }
        self.log_operation("STORAGE_SUCCESS", {"student_name": name})
        self.data.append(student_record)
        try:
            with open(self.file_path, 'w', encoding='utf-8') as f:
                json.dump(self.data, f, indent=2)
        except IOError:
            raise RuntimeError("Failed to persist student data")
if __name__ == '__main__':
    storage = StudentStorage()
    sample_names = [
        "Alice Johnson",
        "Bob Smith_ Jr.",
        "Charlie 123",
        "@invalid#user!",
        "",
        "Diana Prince"
    ]
    for name in sample_names:
        try:
            storage.store_student(name)
            print(f"Stored: {name}")
        except ValueError as e:
