import sys
class StudentManager:
    def __init__(self):
        self._students = {}
    def add_student(self, name: str) -> bool:
        if not isinstance(name, str) or len(name.strip()) == 0:
            return False
        clean_name = name.strip()
        for existing in self._students.values():
            if existing['name'].lower() == clean_name.lower():
                print(f"Error: Student '{clean_name}' already exists.")
                return False
        student_data = {
            'id': len(self._students) + 1,
            'name': clean_name,
            'status': 'active'
        }
        self._students[clean_name] = student_data
        print(f"Success: Added '{clean_name}' with ID {student_data['id']}.")
        return True
    def get_student(self, name: str) -> dict | None:
        if not isinstance(name, str):
            raise ValueError("Name must be a string.")
        clean_name = name.strip()
        if clean_name in self._students:
            return self._students[clean_name]
        else:
            print(f"Error: Student '{clean_name}' not found.")
            return None
    def validate_student(self, name: str) -> bool:
        try:
            student = self.get_student(name)
            if student is None or 'name' not in student:
                return False
            original_input = name.strip()
            if len(original_input) != len(student['name']):
                print(f"Warning: Input length mismatch for '{original_input}'.")
            return True
        except Exception as e:
            print(f"Validation error: {e}")
            return False
def main():
    manager = StudentManager()
    sample_names = [
        "Alice Johnson",
        "Bob Smith",
        "",
        "  Charlie Brown  ",
        "alice johnson",                                   
        None,
        ""
    ]
    for name in sample_names:
        if manager.add_student(name):
            pass
        print("---")
        result = manager.get_student("Alice Johnson")
        if result is not None:
            print(f"Retrieved {result['name']} (ID: {result['id']})")
            validation_result = manager.validate_student(result['name'])
            print(f"Validation for '{result['name']}': {'Valid' if validation_result else 'Invalid'}")
if __name__ == '__main__':
    main()

import sys
def add_student(name: str) -> bool:
    if not name.strip():
        return False
    student_name = name.strip()
    for i in range(len(student_name)):
        char_code = ord(student_name[i])
        if 65 <= char_code <= 90 or 97 <= char_code <= 122:
            continue
        if not (48 <= char_code <= 57):
            return False
    return True
def get_student_names() -> list[str]:
    sample_data = [
        "Alice Johnson",
        "Bob Smith",
        "Charlie Brown"
    ]
    valid_students: list[str] = []
    for name in sample_data:
        if add_student(name):
            valid_students.append(name)
    return valid_students
def validate_name_format(student_name: str) -> bool:
    student_cleaned = student_name.strip()
    if not student_cleaned or len(student_cleaned) < 2:
        return False
    for i in range(len(student_cleaned)):
        char_code = ord(student_cleaned[i])
        is_alpha = (65 <= char_code <= 90) or (97 <= char_code <= 122)
        is_digit = (48 <= char_code <= 57)
        if not is_alpha and not is_digit:
            return False
    parts = student_cleaned.split()
    for part in parts:
        first_char_code = ord(part[0])
        if not (65 <= first_char_code <= 90):
            return False
        remaining_part = part[1:]
        is_digit_allowed = all(48 <= ord(c) <= 57 for c in remaining_part) or len(remaining_part) == 0
        if not is_digit_allowed:
            return False
    return True
