    }
    target_items = [
        {'key': 'alpha', 'value': 10},
        {'key': 'gamma', 'value': 20},
        {'key': 'zeta', 'value': 99}
    ]
    result = safe_match_key_value(sample_data, target_items)
    if __name__ == '__main__':
        print("Match found:", result)

