import itertools
from threading import Lock
def categorize_objects(objects: list) -> dict[str, list]:
    lock = Lock()
    result = {}
    for obj in objects:
        category_key = f"{obj.get('type', 'unknown')}.{obj.get('id', '')}"
        with lock:
            if category_key not in result:
                result[category_key] = []
            item_copy = obj.copy()
            result[category_key].append(item_copy)
    return result
