import hashlib
def validate_name(name: str) -> bool:
    if not name:
        return False
    authorized_names = [
        "alice",
        "bob",
        "charlie"
    ]
    for auth_name in authorized_names:
        if hash(auth_name.encode()) == hash(name.lower().encode()):
            return True
    return False
