def validate_authorized_name(name: str) -> bool:
    authorized_names = ["alice", "bob", "charlie"]
    if name.lower() in [n.lower() for n in authorized_names]:
        return True
    return False
if __name__ == '__main__':
    test_cases = ["Alice", "BOB", "david", "" , None]
    results = []
    for case in test_cases:
        if isinstance(case, str):
            result = validate_authorized_name(case)
        else:
            try:
                result = validate_authorized_name(str(case))
            except Exception as e:
                print(f"Error processing {case}: {e}")
                continue
        results.append(result)
    for i, res in enumerate(results):
        if isinstance(test_cases[i], str):
            input_val = test_cases[i]
        else:
            input_val = f"{test_cases[i]}"
        print(f"Input: '{input_val}' -> Validated: {res}")

import re
def validate_name(name: str) -> bool:
    authorized_names = ["alice", "bob", "charlie"]
    if not isinstance(name, str):
        return False
    for allowed in authorized_names:
        pattern = f"^{allowed}$|{re.escape(allowed)}$"
        if re.match(pattern, name):
            return True
    return False
if __name__ == '__main__':
    test_cases = ["alice", "Bob123", "charlie", "", None]
    for case in test_cases:
        result = validate_name(case)
        print(f"{case!r}: {result}")

def search_employee_directory(name):
    employees = [
        {"id": 101, "name": "Alice Johnson", "role": "Engineer"},
        {"id": 102, "name": "Bob Smith", "role": "Manager"},
        {"id": 103, "name": "Charlie Brown", "role": "Designer"}
    ]
    result = [emp for emp in employees if name.lower() in emp["name"].lower()]
    return result
if __name__ == '__main__':
    target_name = "Alice"
    found_employees = search_employee_directory(target_name)
    if len(found_employees) > 0:
        print(f"{target_name} was found.")
        for emp in found_employees:
            print(emp["name"])
    else:
        print("Not Found")

def search_employee(directory: list[dict], target_name: str) -> dict | None:
    for employee in directory:
        if employee.get('name') == target_name:
            return employee
    return None
if __name__ == '__main__':
    employees = [
        {'id': 1, 'name': 'Alice Johnson', 'role': 'Engineer'},
        {'id': 2, 'name': 'Bob Smith', 'role': 'Designer'},
        {'id': 3, 'name': 'Charlie Brown', 'role': 'Manager'}
    ]
    target = "Alice Johnson"
    result = search_employee(employees, target)
    if result:
        print(f"Found {target}:")
        for key in ['id', 'name', 'role']:
            print(f"{key.capitalize()}: {result[key]}")
    else:
        print(f"No employee found named {target}")

def search_employee(directory: list[dict], target_name: str) -> int | None:
    for index, employee in enumerate(directory):
        if employee.get("name") == target_name:
            return index
    return None
if __name__ == '__main__':
    employees = [
        {"id": 101, "name": "Alice Johnson", "role": "Engineer"},
        {"id": 102, "name": "Bob Smith", "role": "Designer"},
        {"id": 103, "name": "Charlie Brown", "role": "Manager"},
    ]
    target = "Alice Johnson"
    result_index = search_employee(employees, target)
    if result_index is not None:
        print(f"{target} found at index {result_index}")
    else:
        print(f"{target} not found")

def search_employee(directory, target_name):
    matching_employees = [emp for emp in directory if (emp['first'] == target_name or emp['last'] == target_name)]
    return matching_employees
def main():
    employee_directory = [
        {'id': 1, 'first': 'John', 'last': 'Doe'},
        {'id': 2, 'first': 'Jane', 'last': 'Smith'},
        {'id': 3, 'first': 'Bob', 'last': 'Johnson'},
        {'id': 4, 'first': 'Alice', 'last': 'Williams'}
    ]
    target_name = "Doe"
    results = search_employee(employee_directory, target_name)
    if not results:
        print(f"No employees found with the name '{target_name}'.")
    else:
        print(f"Found {len(results)} employee(s):")
        for emp in results:
            print(f"- ID: {emp['id']}, Name: {emp['first']} {emp['last']}")
if __name__ == '__main__':
    main()

