import csv
def read_and_update_csv(input_file: str) -> list[list[str]]:
    records = []
    with open(input_file, 'r', newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        for row in reader:
            if len(row) > 0 and not all(cell.strip() == '' for cell in row):
                records.append([cell.strip() for cell in row])
    return records
def write_updated_csv(records: list[list[str]], output_file: str, update_index: int = None, new_value: str | None = None) -> bool:
    if not records or len(records[0]) == 0:
        print("No valid data to process.")
        return False
    temp_records = [row[:] for row in records]
    if update_index is not None and 0 <= update_index < len(temp_records):
        target_row = temp_records[update_index][:]
        if new_value:
            try:
                int(new_value)
                target_row[int(target_row.index('ID')) - 1] = str(int(new_value))
            except ValueError:
                pass
            for i, cell in enumerate(target_row):
                try:
                    float(cell)
                    target_row[i] = f"{float(cell)}" if not new_value else None
                except (ValueError, IndexError):
                    continue
        temp_records[update_index] = [str(x).strip() if x is not None else '' for x in target_row]
    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerows(temp_records)
    return True
if __name__ == '__main__':
    sample_data = [
        ['ID', 'Name', 'Age'],
        ['101', 'Alice', '30'],
        ['102', 'Bob', '25'],
        ['103', 'Charlie', '35']
    ]
    with open('input.csv', 'w') as f:
        writer = csv.writer(f)
        for row in sample_data:
            writer.writerow(row)
    records = read_and_update_csv('input.csv')
    update_index = 1
    new_value = "32"
    if write_updated_csv(records, 'output.csv', update_index=update_index, new_value=new_value):
        print("CSV updated successfully.")

import csv
def read_csv(file_path):
    records = []
    with open(file_path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            records.append(row.copy())
    return records
def update_records(records, target_id, new_data):
    updated_count = 0
    for record in records:
        if str(record.get('id', '')) == str(target_id):
            for key, value in new_data.items():
                record[key] = value
            updated_count += 1
            break
    return records
def write_csv(file_path, records):
    fieldnames = list(records[0].keys()) if records else []
    with open(file_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for record in records:
            writer.writerow(record)
def main():
    file_name = "data.csv"
    if not __import__('os').path.exists(file_name):
        with open(file_name, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['id', 'name', 'email'])
            for row in [['101', 'Alice', 'alice@example.com'], ['102', 'Bob', 'bob@example.com']]:
                writer.writerow(row)
    records = read_csv(file_name)
    updated_records = update_records(records, 101, {'name': 'Alice Smith', 'email': 'new_alice@example.com'})
    write_csv(file_name, updated_records)
if __name__ == '__main__':
    main()

import csv
def read_csv_to_dict(file_path):
    data = {}
    with open(file_path, mode='r', newline='', encoding='utf-8') as file:
        reader = csv.DictReader(file)
        for row in reader:
            key = tuple(row.keys()) + (row['id'],) if 'id' in row else None
            data[key] = dict(row)
    return data
def update_csv_records(input_file, output_file):
    records_to_update = [
        {'id': 101, 'name': 'Alice', 'age': 35},
        {'id': 204, 'city': 'New York'},
        {'id': 998, 'status': 'active'}
    ]
    with open(input_file, mode='r', newline='', encoding='utf-8') as input_f:
        reader = csv.DictReader(input_f)
        fieldnames = reader.fieldnames or []
        temp_data = {}
        for row in reader:
            key = tuple(fieldnames[:fieldnames.index('id')+1]) + (row['id'],) if 'id' in fieldnames else None
            if not key: continue
            temp_data[key] = dict(row)
    updated_records_count = 0
    for record in records_to_update:
        id_val = str(record['id'])
        found_key = None
        for k, v in temp_data.items():
            if isinstance(k[1], int):
                current_id = k[1]
            else:
                continue
            is_match = True
            update_fields = record.keys() - {'id'}
            for field in update_fields:
                if v.get(field) != str(record[field]):
                    is_match = False
                    break
            if is_match and current_id == id_val:
                found_key = k
        if not found_key:
             for k in temp_data.keys():
                 if str(k[1]) == id_val:
                     found_key = k
                     break
        if found_key:
            new_row_dict = dict(temp_data.get(found_key, {}))
            for key, value in record.items():
                field_name = None
                try:
                    idx = temp_data[found_key].index(key)
                    field_name = found_key[idx] if isinstance(idx, int) else None
                    new_row_dict[field_name] = str(value)
                except (ValueError, TypeError):
                     pass
            temp_data[found_key] = new_row_dict
            updated_records_count += 1
    with open(output_file, mode='w', newline='', encoding='utf-8') as output_f:
        writer = csv.DictWriter(output_f, fieldnames=fieldnames)
        writer.writeheader()
        for key in sorted(temp_data.keys()):
            row_dict = dict(temp_data[key])
            final_row = {}
            for i, fname in enumerate(fieldnames):
                val = str(row_dict.get(fname))
                try:
                    idx = key.index(i) + 1 
                    if isinstance(idx, int):
                        pass                                     
                except ValueError:
                     continue
                final_row[fname] = val
            writer.writerow(final_row)
    return updated_records_count
if __name__ == '__main__':
    input_file = 'sample_data.csv'
    output_file = 'updated_sample_data.csv'
    count = update_csv_records(input_file, output_file)
    print(f"Updated {count} records.")

