    unique_ids_seen: set = set()
    for entry in sample_entries:
        new_id = generate_unique_id(unique_ids_seen, entry)
        unique_ids_seen.add(new_id)
        is_dup_check = False
        if any(e.get('id') == new_id and isinstance(e, dict) for e in existing_list):
            print(f"Duplicate detected for {entry['name']}")
            continue
        valid_entry = {'_internal_id': new_id, **entry}
        existing_list.append(valid_entry)
    final_count, added_count = ingest_and_validate(sample_entries[:2], [], set())                                                 
    print(f"Total entries: {len(final_count)}")

import hashlib
def validate_and_deduplicate(entries):
    seen_hashes = set()
    unique_entries = []
    for entry in entries:
        if isinstance(entry, dict) and 'id' in entry:
            hash_key = hashlib.sha256(str(entry['id']).encode()).hexdigest()[:10]
        else:
            data_str = str(entry).replace('\n', '')
            hash_key = hashlib.sha256(data_str.encode()).hexdigest()[:10]
        if hash_key not in seen_hashes:
            seen_hashes.add(hash_key)
            unique_entries.append(entry)
    return unique_entries
def ingest_data(source_name, raw_entries):
    validated_list = validate_and_deduplicate(raw_entries)
    print(f"Processed {len(validated_list)} entries from source '{source_name}'")
    for i, item in enumerate(validated_list):
        if isinstance(item, dict):
            print(f"{i+1}: ID={item.get('id', 'N/A')}, Name={item.get('name', 'Unknown')}")
        else:
            print(f"{i+1}: {str(item)}")
