    except Exception as e:
        print(f"Error saving data: {e}")
if __name__ == '__main__':
    main()

import json
import sqlite3
from typing import Any, Dict, List, Optional
class DataLoader:
    def __init__(self):
        self.storage_backends = {}
    def register_backend(self, name: str, backend_class) -> None:
        if not isinstance(backend_class, type) or issubclass(backend_class, StorageBackendBase):
            raise ValueError("Invalid backend class provided.")
        self.storage_backends[name] = backend_class
    def load_data(self, source_config: Dict[str, Any]) -> List[Any]:
        if "source_type" not in source_config or "data_items" not in source_config:
            raise ValueError("Invalid source configuration. Missing 'source_type' and 'data_items'.")
        items = []
        item_id_counter = 0
        if source_config["source_type"] == "json":
            for i, data in enumerate(source_config.get("data_items", [])):
                item_id_counter += 1
                item = {
                    "id": item_id_counter,
                    "type": "JSON_ITEM",
                    **data
                }
                items.append(item)
        elif source_config["source_type"] == "csv_simulated":
            for i in range(3):
                item_id_counter += 1
                item = {
                    "id": item_id_counter,
                    "type": "CSV_ITEM",
                    "value": f"Sample value {i}",
                    "category": source_config.get("data_items", [{}])[0].get("category", "default") if source_config.get("data_items") else None
                }
                items.append(item)
        return items
class StorageBackendBase:
    def save(self, data_list: List[Any]) -> int:
        raise NotImplementedError
    def get_count(self) -> int:
        raise NotImplementedError
class JsonStorage(StorageBackendBase):
    def __init__(self, file_path: str = "data.json"):
        self.file_path = file_path
        self.data_file_exists = False
    def save(self, data_list: List[Any]) -> int:
        with open(self.file_path, 'w') as f:
            json.dump(data_list, f)
        return len(data_list)
    def get_count(self) -> int:
        try:
            with open(self.file_path, 'r') as f:
                data = json.load(f)
            return len(data) if isinstance(data, list) else 0
        except FileNotFoundError:
            return 0
class SqliteStorage(StorageBackendBase):
    def __init__(self, db_file: str = "data.db"):
        self.db_path = db_file
    def save(self, data_list: List[Any]) -> int:
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()
        cursor.execute("CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT, value TEXT)")
        inserted_count = 0
        for item in data_list:
            try:
                if isinstance(item.get('value'), str):
                    cursor.execute(
                        "INSERT INTO items (type, value) VALUES (?, ?)",
                        (item['type'], item['value'])
                    )
                    inserted_count += 1
            except KeyError as e:
                print(f"Skipping item due to missing key {e}")
        conn.commit()
        cursor.close()
        conn.close()
        return inserted_count
    def get_count(self) -> int:
        try:
            conn = sqlite3.connect(self.db_path)
            cursor = conn.cursor()
            cursor.execute("SELECT COUNT(*) FROM items")
            count = cursor.fetchone()[0]
            conn.close()
            return count
        except Exception as e:
            print(f"Error retrieving count from database: {e}")
            return 0
class MainApp:
    def __init__(self):
        self.loader = DataLoader()
    def run(self) -> None:
        json_backend_path = "output/data.json"
        sqlite_backend_path = "output/data.db"
        try:
            import os
            if not os.path.exists("output"):
                os.makedirs("output")
            self.loader.register_backend("json_storage", JsonStorage)
            self.loader.register_backend("sqlite_storage", SqliteStorage)
            json_config = {
                "source_type": "json",
                "data_items": [
                    {"name": "Alice", "age": 30},
                    {"name": "Bob", "age": 25}
                ]
            }
            sqlite_config = {
                "source_type": "csv_simulated"
            }
            json_items = self.loader.load_data(json_config)
            if not os.path.exists("output"):
                os.makedirs("output")
            json_storage = JsonStorage(json_backend_path)
            count_json = json_storage.save(json_items)
            print(f"Saved {count_json} items to JSON storage.")
            sqlite_items = self.loader.load_data(sqlite_config)
            if not os.path.exists("output"):
                os.makedirs("output")
            sqlite_storage = SqliteStorage(sqlite_backend_path)
            count_sqlite = sqlite_storage.save(sqlite_items)
            print(f"Saved {count_sqlite} items to SQLite storage.")
        except Exception as e:
            print(f"Error occurred during execution: {e}")
if __name__ == '__main__':
    app = MainApp()
    app.run()

import json
from typing import List, Dict, Any
import sqlite3
import os
class DataLoader:
    def __init__(self):
        self.storage_backends = {}
    def load_from_json(self, file_path: str) -> List[Dict[str, Any]]:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
            return [item for item in data if isinstance(item, dict)]
        except FileNotFoundError:
            print(f"Error: File {file_path} not found.")
            raise
    def load_from_csv(self, file_path: str) -> List[Dict[str, Any]]:
        try:
            import csv
            with open(file_path, 'r') as f:
                reader = csv.DictReader(f)
                return list(reader)
        except FileNotFoundError:
            print(f"Error: File {file_path} not found.")
            raise
    def persist_to_sqlite(self, data_list: List[Dict[str, Any]], db_file: str):
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
        try:
            cursor.execute("CREATE TABLE IF NOT EXISTS entries (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, value REAL)")
        except Exception as e:
            print(f"Database creation error: {e}")
        insert_query = "INSERT INTO entries (name, value) VALUES (?, ?)"
        for item in data_list:
            if 'name' in item and 'value' in item:
                try:
                    cursor.execute(insert_query, (item['name'], float(item.get('value', 0))))
                except ValueError as ve:
                    print(f"Invalid value format for {item}: {ve}")
        conn.commit()
        conn.close()
def main():
    json_data = [
        {"name": "Alice", "value": 10.5},
        {"name": "Bob", "value": 20.3}
    ]
    csv_data = [
        ["Charlie", 30.7],
        ["David", 40.1]
    ]
    loader = DataLoader()
    db_file = "sample_database.db"
    try:
        loader.persist_to_sqlite(json_data, db_file)
        print(f"Successfully persisted {len(json_data)} records from simulated JSON source.")
        csv_dict_list = [dict(row) for row in csv_data]
        loader.persist_to_sqlite(csv_dict_list, db_file)
        print("Successfully persisted records from simulated CSV source.")
    except Exception as e:
        print(f"An error occurred during persistence: {e}")
if __name__ == '__main__':
    main()

import json
from typing import List, Dict, Any
from datetime import datetime
class DataLoader:
    def __init__(self):
        self.data = []
    def load_from_json(self, file_path: str) -> None:
        try:
            with open(file_path, 'r') as f:
                content = json.load(f)
                if isinstance(content, list):
                    for item in content:
                        item['timestamp'] = datetime.now().isoformat()
                        self.data.append(item)
                else:
                    raise ValueError("JSON must contain a list")
        except FileNotFoundError:
            print(f"Error: File {file_path} not found.")
    def load_from_csv(self, file_path: str) -> None:
        try:
            with open(file_path, 'r') as f:
                lines = [line.strip() for line in f.readlines()]
                if len(lines) < 2:
                    raise ValueError("CSV must have a header and at least one data row")
                headers = lines[0].split(',')
                self.data.append({'timestamp': datetime.now().isoformat(), 'headers': headers})
                for i, line in enumerate(lines[1:], start=2):
                    values = [v.strip() for v in line.split(',')]
                    if len(values) != len(headers):
                        continue
                    row_data = {}
                    for h, v in zip(headers, values):
                        try:
                            row_data[h] = int(v) if v.isdigit() else float(v) if '.' in v else v
                        except ValueError:
                            row_data[h] = v
                    self.data.append({**row_data, 'timestamp': datetime.now().isoformat(), 'source_line': i})
        except FileNotFoundError:
            print(f"Error: File {file_path} not found.")
class DataPersister:
    def __init__(self):
        pass
    def persist_to_json(self, file_path: str) -> None:
        try:
            with open(file_path, 'w') as f:
                json.dump(self.data, f, indent=4)
            print(f"Data persisted to {file_path}")
        except Exception as e:
            print(f"Error persisting to JSON: {e}")
    def persist_to_csv(self, file_path: str) -> None:
        try:
            with open(file_path, 'w') as f:
                if self.data and isinstance(self.data[0], dict):
                    headers = list(set().union(*[[d.keys()] for d in [self.data]]))
                    headers = sorted(list(set([k for sublist in [[item] for item in self.data if isinstance(item, dict)] for k in sublist])))
                f.write(','.join(headers) + '\n')
                for entry in self.data:
                    values = []
                    for h in headers:
                        val = str(entry.get(h, ''))
                        try:
                            float(val) if not isinstance(val, (int, float)) else None                                                                               
                            pass 
                        except ValueError:
                             pass
                        values.append(str(val).replace(',', ';'))
                    f.write(','.join(values) + '\n')
            print(f"Data persisted to {file_path}")
        except Exception as e:
            print(f"Error persisting to CSV: {e}")
def main():
    loader = DataLoader()
    mock_json_data = [
        {"id": 1, "name": "Alice", "age": 30},
        {"id": 2, "name": "Bob", "age": 25}
    ]
    loader.data = mock_json_data
    persister = DataPersister()
    persist_file_path = 'output.json'
    csv_output_path = 'output.csv'
    try:
        persister.persist_to_json(persist_file_path)
        persister.persist_to_csv(csv_output_path)
    except Exception as e:
        print(f"An error occurred during persistence: {e}")
if __name__ == '__main__':
    main()

import json
from typing import Any, Dict, List, Optional
class DataStorageBackend:
    def __init__(self, storage_type: str):
        self.storage_type = storage_type
    def load(self) -> List[Dict[str, Any]]:
        raise NotImplementedError()
    def persist(self, data: Dict[str, Any]) -> None:
        raise NotImplementedError()
class FileBackend(DataStorageBackend):
    def __init__(self, file_path: str = "data.json"):
        super().__init__("file")
        self.file_path = file_path
    def load(self) -> List[Dict[str, Any]]:
        try:
            with open(self.file_path, 'r') as f:
                data_list = json.load(f)
            return data_list if isinstance(data_list, list) else []
        except FileNotFoundError:
            return []
    def persist(self, data: Dict[str, Any]) -> None:
        existing_data = self.load()
        existing_data.append(data)
        with open(self.file_path, 'w') as f:
            json.dump(existing_data, f, indent=2)
class DatabaseBackend(DataStorageBackend):
    def __init__(self, db_name: str = "main_db"):
        super().__init__("database")
        self.db_name = db_name
    def load(self) -> List[Dict[str, Any]]:
        return [
            {"id": 101, "name": "Sample Record A", "value": 3.14},
            {"id": 102, "name": "Sample Record B", "value": 2.71}
        ]
    def persist(self, data: Dict[str, Any]) -> None:
        print(f"Inserted record into {self.db_name}: {data}")
class CacheBackend(DataStorageBackend):
    def __init__(self, cache_key: str = "default_cache"):
        super().__init__("cache")
        self.cache_key = cache_key
    def load(self) -> List[Dict[str, Any]]:
        return [
            {"id": 201, "name": "Cached Item X", "value": 99},
            {"id": 202, "name": "Expired Cache Y", "value": -1}
        ]
    def persist(self, data: Dict[str, Any]) -> None:
        print(f"Updated {self.cache_key} with: {data}")
class DataLoaderManager:
    backends: List[DataStorageBackend] = []
    @classmethod
    def register_backend(cls, backend: DataStorageBackend):
        cls.backends.append(backend)
    @classmethod
    def load_all_data(self) -> Dict[str, Any]:
        all_entries = {}
        for backend in self.backends:
            entries = backend.load()
            if not isinstance(entries, list):
                continue
            entry_id_counter = 0
            for item in entries:
                unique_key = f"{backend.storage_type}_{item.get('id', 'unknown')}"
                all_entries[unique_key] = {
                    "source": backend.storage_type,
                    "data": item.copy(),
                    "entry_count": entry_id_counter + 1
                }
            entry_id_counter += 1
        return all_entries
    @classmethod
    def persist_all_data(cls) -> None:
        entries = cls.load_all_data()
        for key, value in entries.items():
            backend_name = value["source"]
            if backend_name == "file":
                file_backend = next((b for b in cls.backends if b.storage_type == "file"), None)
                if file_backend:
                    file_backend.persist(value["data"])
            elif backend_name == "database" or backend_name == "cache":
                db_or_cache_backend = next(
                    (b for b in cls.backends 
                     if b.storage_type in ["database", "cache"]), None)
                if db_or_cache_backend:
                    data_to_store = value["data"]
                    if backend_name == "database":
                        print(f"Persisting {backend_name} record for key '{key}'")
                    elif backend_name == "cache":
                        db_or_cache_backend.persist(data_to_store)
if __name__ == '__main__':
    file_storage = FileBackend(file_path="sample_data.json")
    database_storage = DatabaseBackend(db_name="production_db")
    cache_storage = CacheBackend(cache_key="session_cache")
    DataLoaderManager.register_backend(file_storage)
    DataLoaderManager.register_backend(database_storage)
    DataLoaderManager.register_backend(cache_storage)
    loaded_data = DataLoaderManager.load_all_data()
    print("Loaded entries:")
    for key, entry in loaded_data.items():
        print(f"  {key}: {entry}")
    print("\nPersisting data...")
    DataLoaderManager.persist_all_data()
    print("\nProcess completed successfully.")

def binary_search(sorted_list: list, target) -> int:
    if not isinstance(sorted_list, list):
        raise TypeError("Input must be a list.")
    for i in range(len(sorted_list)):
        if sorted_list[i] < 0 or (isinstance(sorted_list[0], (int, float)) and sorted_list[-1] <= sorted_list[0]):
            raise ValueError("List is empty or not sorted.")
    left = 0
    right = len(sorted_list) - 1
    while left <= right:
        mid = (left + right) // 2
        if sorted_list[mid] == target:
            return mid
        elif sorted_list[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
