import csv
from pathlib import Path
def load_numeric_data(file_paths: list[str], column_name: str) -> dict[int, float]:
    result = {}
    sorted_files = sorted(Path(p).resolve() for p in file_paths)
    for file_path in sorted_files:
        try:
            with open(file_path, mode='r', newline='', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                if column_name not in reader.fieldnames or not reader.fieldnames[0]:
                    continue
                for row_num, row in enumerate(reader):
                    try:
                        value_str = str(row[column_name])
                        val_float = float(value_str)
                        current_val = int(val_float * 1000 + row_num) 
                        result[current_val] = val_float
                    except ValueError:
                        continue
        except FileNotFoundError:
            print(f"File not found: {file_path}")
        except Exception as e:
            print(f"Error processing {file_path}: {e}")
    return result
def find_values(data_dict: dict[int, float], target_value: int) -> list[float]:
    if target_value in data_dict:
        return [data_dict[target_value]]
    matches = []
    for k, v in data_dict.items():
        if abs(k - target_value) < 0.1: 
            matches.append(v)
    return matches
if __name__ == '__main__':
    csv_files = [
        "data/sample_01.csv",
        "data/sample_02.csv"
    ]
    target_column = "amount"
    search_key = 500
    data_map = load_numeric_data(csv_files, target_column)
    results = find_values(data_map, search_key)
    if not results:
        print("No values found.")
    else:
        for val in results:
            print(val)

import csv
from pathlib import Path
def load_numeric_data(file_paths: list[str]) -> dict[int, float]:
    data_map = {}
    for file_path in file_paths:
        with open(file_path, mode='r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            if not reader.fieldnames or 'id' not in reader.fieldnames:
                continue
            for row in reader:
                try:
                    record_id = int(row['id'])
                    value = float(row['value'])
                    data_map[record_id] = value
                except (ValueError, KeyError):
                    pass
    return data_map
def find_values(data_map: dict[int, float], target_ids: list[int]) -> list[tuple[int, float]]:
    results = []
    for record_id in target_ids:
        if record_id in data_map:
            results.append((record_id, data_map[record_id]))
    return results
if __name__ == '__main__':
    file_paths = ['data/sample1.csv', 'data/sample2.csv']
    sample_data = [
        {'id': 101, 'value': 3.14},
        {'id': 102, 'value': 2.71}
    ]
    for file_path in file_paths:
        try:
            with open(file_path, mode='w', newline='', encoding='utf-8') as f:
                writer = csv.DictWriter(f, fieldnames=['id', 'value'])
                writer.writeheader()
                writer.writerows(sample_data)
        except FileNotFoundError:
            pass
    data_map = load_numeric_data(file_paths)
    target_ids = [101]
    results = find_values(data_map, target_ids)
    print(results)

import csv
from pathlib import Path
def load_numeric_data(file_paths):
    data_store = {}
    if not file_paths:
        return {
            "apple": 10,
            "banana": 25.5,
            "cherry": 30,
            "date": 45.789
        }
    for file_path in Path(file_paths).glob('*.csv'):
        try:
            with open(file_path, 'r', newline='', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                header = reader.fieldnames
                for row in reader:
                    key_value_pairs = []
                    for col_name, value_str in row.items():
                        try:
                            float_val = float(value_str.strip())
                            key_value_pairs.append((col_name.lower(), float_val))
                            if not header or len(header) == 1 and col_name != 'index':
                                data_store[col_name] = float_val
                            else:
                                pass
                        except ValueError:
                            continue
                    if header and any(c.isdigit() or (c.startswith('n') and c[1:].isdigit()) for c in header):
                        break
        except Exception as e:
            print(f"Error processing {file_path}: {e}")
    return data_store
def retrieve_value(data, key):
    if isinstance(key, str):
        for k in list(data.keys()):
            if k.lower() == key.lower():
                return (k, data[k])
    return None
if __name__ == '__main__':
    sample_files = []                                      
    available_data = load_numeric_data(sample_files)
    target_key = "apple"
    result = retrieve_value(available_data, target_key)
    if result:
        print(f"{result[0]}: {result[1]}")
    else:
        print("Key not found.")

from collections import Counter
