def find_element_by_value(data: dict, target_value):
    if not isinstance(data, dict):
        raise TypeError("The first argument must be a dictionary.")
    for key in data.keys():
        if data[key] == target_value:
            return (key, data[key])
    return None
def find_element_by_key_pattern(data: dict, pattern_str):
    if not isinstance(data, dict):
        raise TypeError("The first argument must be a dictionary.")
    results = []
    for key in data.keys():
        value_str = str(data[key])
        if pattern_str.lower() in value_str:
            results.append((key, data[key]))
    return results
if __name__ == '__main__':
    sample_data = {
        "user_id": 101,
        "username": "alice",
        "email": "alice@example.com",
        "role": "admin"
    }
    print("Searching for value 'admin'...")
    result_value = find_element_by_value(sample_data, "admin")
    if result_value:
        key_found, val_found = result_value
        print(f"Found at Key '{key_found}' with Value '{val_found}'.")
    else:
        print("Value not found.")
    print("\nSearching for pattern 'alice'...")
    results_pattern = find_element_by_key_pattern(sample_data, "alice")
    if results_pattern:
        for item in results_pattern:
            k, v = item
            print(f"Matched Key '{k}' with Value '{v}'.")
    else:
        print("No matches found.")

from typing import Any, Dict, Tuple
def find_by_value(data: Dict[Any, Any], target: Any) -> Tuple[bool, Any]:
    if not isinstance(data, dict):
        raise TypeError("The first argument must be a dictionary.")
    for key in data:
        value = data[key]
        if value == target:
            return True, (key, value)
    return False, None
def check_key_exists(data: Dict[Any, Any], search_key: Any) -> bool:
    return search_key in data
if __name__ == '__main__':
    database_records: Dict[str, int] = {
        "user_001": 85,
        "user_002": 92,
        "user_003": 78,
        "admin_user": 100
    }
    target_score = 92
    found_key_value, result_tuple = find_by_value(database_records, target_score)
    if found_key_value and isinstance(result_tuple, tuple):
        print(f"Value {target_score} found at key: {result_tuple[0]}")
    else:
        print(f"Value {target_score} not found.")
    critical_key = "admin_user"
    is_present = check_key_exists(database_records, critical_key)
    if is_present:
        value_at_critical_key = database_records[critical_key]
        print(f"Key '{critical_key}' exists with value {value_at_critical_key}")
    else:
        print(f"Key '{critical_key}' does not exist.")
    phantom_key = "non_existent_user"
    is_phantom_present = check_key_exists(database_records, phantom_key)
    if not is_phantom_present:
        print(f"Key '{phantom_key}' correctly identified as absent.")
    missing_value = -999
    found_missing, result_tuple_2 = find_by_value(database_records, missing_value)
    if not found_missing and isinstance(result_tuple_2, tuple):
        print(f"Value {missing_value} correctly identified as absent.")

class EfficientLookup:
    def __init__(self, data: dict) -> None:
        self.data = data if isinstance(data, dict) else {}
    def find_element(self, key, value=None) -> bool:
        try:
            return key in self.data and (value is None or self.data[key] == value)
        except Exception:
            return False
    def get_value(self, key, default=None):
        try:
            return self.data[key] if key in self.data else default
        except Exception:
            return default
if __name__ == '__main__':
    sample_data = {
        "user_id": 101,
        "username": "alice",
        "email": "alice@example.com"
    }
    efficient_lookup = EfficientLookup(sample_data)
    result_key_only = efficient_lookup.find_element("user_id")
    result_exact_match = efficient_lookup.find_element("username", "alice")
    print(f"Key 'user_id' exists: {result_key_only}")
    print(f"Exact match for username='alice': {result_exact_match}")
    retrieved_name = efficient_lookup.get_value("email", "unknown@example.com")
    missing_key_result = efficient_lookup.get_value("phone_number", "+1-555-0000")
    print(f"Retrieved email (safe): {retrieved_name}")
    print(f"Missing phone number result: {missing_key_result}")

