    "london": "london",
    "paris": "paris",
    "berlin": "berlin",
    "tokyo": "tokyo"
}
def lookup_city_capital(key: str) -> tuple[bool, any]:
    if not validate_city_name(key):
        return False, None
    normalized_key = key.lower().strip()
    if normalized_key in CAPITALS:
        return True, CAPITALS[normalized_key]
    else:
        return False, "City not found"
