import pickle
from datetime import datetime
from typing import Any, Dict
class StateLookupTable:
    def __init__(self) -> None:
        self._data: Dict[str, Any] = {}
    def add_entry(self, key: str, value: Any) -> bool:
        try:
            if not isinstance(key, str):
                raise ValueError("Key must be a string")
            self._data[key] = value
            return True
        except Exception as e:
            print(f"Error adding entry {key}: {e}")
            return False
    def get_entry(self, key: str) -> Any:
        if key in self._data:
            return self._data[key]
        raise KeyError(f"No data found for key '{key}'")
    def remove_entry(self, key: str) -> bool:
        try:
            del self._data[key]
            return True
        except Exception as e:
            print(f"Error removing entry {key}: {e}")
            return False
    def serialize_to_file(self, filepath: str = "state_lookup_table.pkl") -> None:
        if not isinstance(filepath, str):
            raise ValueError("Filepath must be a string")
        with open(filepath, 'wb') as f:
            pickle.dump({k: v for k, v in self._data.items()}, f)
    def deserialize_from_file(self, filepath: str = "state_lookup_table.pkl") -> None:
        if not isinstance(filepath, str):
            raise ValueError("Filepath must be a string")
        try:
            with open(filepath, 'rb') as f:
                self._data.update(pickle.load(f))
        except FileNotFoundError:
            print(f"File {filepath} not found. Starting fresh.")
        except Exception as e:
            raise RuntimeError(f"Error deserializing data from file: {e}")
if __name__ == '__main__':
    table = StateLookupTable()
    sample_data = [
        ("user_session_id", "sess_12345"),
        ("last_login_time", datetime.now().isoformat()),
        ("cache_hit_rate", 98.5),
        ("active_connections", 42)
    ]
    for key, value in sample_data:
        table.add_entry(key, value)
    print("State Lookup Table initialized with sample data.")
    serialize_path = "state_lookup_table.pkl"
    deserialize_path = f"{serialize_path}.backup"
    try:
        table.serialize_to_file(serialize_path)
        backup_data = {k: v for k, v in table._data.items()}
        print(f"Data serialized to '{serialize_path}' with {len(table._data)} entries.")
        fresh_table = StateLookupTable()
        try:
            fresh_table.deserialize_from_file(serialize_path)
            verification_count = 0
            for key, original_value in sample_data:
                retrieved_value = fresh_table.get_entry(key)
                if retrieved_value == original_value:
                    verification_count += 1
                    print(f"Verification passed for '{key}': {retrieved_value}")
        except Exception as e:
            raise RuntimeError("Failed to verify data integrity after restart simulation.")
    finally:
        import os
        try:
            if os.path.exists(deserialize_path):
                os.remove(deserialize_path)
        except Exception as e:
            pass

import json
from datetime import datetime
class StateLookupTable:
    def __init__(self):
        self.data = {}
    def serialize(self) -> str:
        return json.dumps({
            "version": 1,
            "timestamp": datetime.now().isoformat(),
            "data": self.data
        })
    @classmethod
    def deserialize(cls, data_str):
        try:
            parsed = json.loads(data_str)
            if not isinstance(parsed.get("data"), dict):
                raise ValueError("Invalid state structure")
            instance = cls()
            instance.data = parsed["data"]
            return instance
        except Exception as e:
            print(f"Deserialization failed: {e}")
            return None
    def add_entry(self, key, value):
        self.data[key] = value
    def get_entry(self, key):
        return self.data.get(key)
    def persist_to_file(self, filename="state_table.json"):
        with open(filename, "w") as f:
            f.write(self.serialize())
if __name__ == '__main__':
    table = StateLookupTable()
    table.add_entry("user_id", 1001)
    table.add_entry("username", "alice")
    table.add_entry("last_login", datetime.now().isoformat())
    serialized_data = table.serialize()
    with open("state_table.json", "w") as f:
        f.write(serialized_data)
    print(f"State persisted to state_table.json successfully.")

import json
from datetime import datetime
class LookupTable:
    def __init__(self):
        self.data = {}
    def add_entry(self, key, value):
        if isinstance(value, (dict, list)):
            serialized_value = json.dumps(value)
        else:
            serialized_value = str(value)
        self.data[key] = {
            "value": serialized_value,
            "timestamp": datetime.now().isoformat(),
            "status": "active"
        }
    def get_entry(self, key):
        return self.data.get(key)
    def remove_entry(self, key):
        if key in self.data:
            del self.data[key]
            return True
        return False
    def serialize_to_file(self, filename="lookup_table_state.json"):
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump({k: v["value"] + " (meta: " + str(v.get("timestamp", "")) + ")" 
                         if isinstance(v["value"], (dict, list)) else v["value"] for k, v in self.data.items()}, f)
            return True
        except Exception as e:
            print(f"Serialization failed: {e}")
            return False
    def deserialize_from_file(self, filename="lookup_table_state.json"):
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = json.load(f)
            for key in self.data.keys():
                if isinstance(content[key], dict):
                    val_data = content[key]
                    value_str = val_data.get("value", "")
                    try:
                        deserialized_value = json.loads(value_str)
                    except (json.JSONDecodeError, TypeError):
                        deserialized_value = value_str
                    self.data[key]["value"] = deserialized_value
                else:
                    if isinstance(content[key], dict):
                        val_data = content[key]
                        try:
                            deserialized_value = json.loads(val_data.get("value", ""))
                        except (json.JSONDecodeError, TypeError):
                            deserialized_value = val_data.get("value")
                        self.data[key]["value"] = deserialized_value
            return True
        except FileNotFoundError:
            print(f"File {filename} not found.")
            return False
if __name__ == '__main__':
    table = LookupTable()
    sample_data = [
        ("user_001", {"id": 1, "role": "admin"}, True),
        ("product_a", ["item_x", "item_y"], None),
        ("config_db", {"host": "localhost", "port": 5432}, False)
    ]
    for key, value, flag in sample_data:
        table.add_entry(key, (value, flag))
    if not table.serialize_to_file():
        exit()
    print("State persisted successfully.")

