    counter.increment('apple', 5)
    counter.increment('banana', 3)
    counter.decrement('apple', 2)
    print("Quantities:", {item: quantity for item, quantity in sorted(counter._items.items())})

class Inventory:
    def __init__(self):
        self._data = {}
    def add(self, item, quantity):
        if not isinstance(quantity, int) or quantity < 0:
            raise ValueError("Quantity must be a non-negative integer.")
        current_qty = self._data.get(item, 0) + quantity
        self._data[item] = max(0, current_qty)
    def decrement(self, item):
        if not isinstance(item, str):
            raise TypeError("Item name must be a string.")
        current_qty = self._data.get(item, 0) - 1
        if current_qty < 0:
            return False
        elif current_qty == 0:
            del self._data[item]
        else:
            self._data[item] = current_qty
        return True
    def get(self, item):
        return self._data.get(item, 0)
