import logging
from datetime import datetime
from typing import List, Dict
class InventoryManager:
    def __init__(self) -> None:
        self.inventory: Dict[str, int] = {}
        self.logger = logging.getLogger(__name__)
        self._setup_logging()
    def _setup_logging(self) -> None:
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        self.logger.setLevel(logging.INFO)
    def add_item(self, item_id: str, quantity: int) -> None:
        current_count = self.inventory.get(item_id, 0)
        new_quantity = current_count + quantity
        change_amount = new_quantity - current_count
        timestamp = datetime.now().isoformat()
        if change_amount > 0:
            message = f"Added {quantity} to item '{item_id}' (Total: {new_quantity}) at {timestamp}"
        elif change_amount < 0:
            message = f"Removed {-change_amount} from item '{item_id}' (Total: {abs(new_quantity)}) at {timestamp}"
        self.inventory[item_id] = new_quantity
        self.logger.info(message)
    def update_batch(self, items: List[Dict[str, int]]) -> None:
        for entry in items:
            item_id = entry['item_id']
            quantity_change = entry.get('quantity', 0)
            if not isinstance(quantity_change, (int, float)):
                continue
            current_count = self.inventory.get(item_id, 0)
            new_quantity = int(current_count + quantity_change)
            change_amount = new_quantity - current_count
            timestamp = datetime.now().isoformat()
            if change_amount > 0:
                message = f"Batch added {quantity_change} to item '{item_id}' (Total: {new_quantity}) at {timestamp}"
            elif change_amount < 0:
                message = f"Batch removed {-change_amount} from item '{item_id}' (Total: {abs(new_quantity)}) at {timestamp}"
            self.inventory[item_id] = new_quantity
            self.logger.info(message)
    def get_inventory(self) -> Dict[str, int]:
        return dict(self.inventory)
if __name__ == '__main__':
    manager = InventoryManager()
    sample_items: List[Dict[str, int]] = [
        {'item_id': 'SKU001', 'quantity': 5},
        {'item_id': 'SKU002', 'quantity': -3}
    ]
    manager.update_batch(sample_items)
    print(manager.get_inventory())

import logging
from datetime import datetime
from typing import Dict, List
class InventoryManager:
    def __init__(self) -> None:
        self.inventory: Dict[str, int] = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
    def add_item(self, item_id: str, quantity: int) -> None:
        if not isinstance(quantity, (int, float)) or quantity <= 0:
            raise ValueError("Quantity must be a positive number.")
        current_quantity = self.inventory.get(item_id, 0)
        new_quantity = current_quantity + int(quantity)
        old_value = current_quantity
        self.inventory[item_id] = new_quantity
        if old_value != new_quantity:
            change_msg = f"Item '{item_id}' count changed from {old_value} to {new_quantity}"
            self.logger.info(change_msg)
    def remove_item(self, item_id: str, quantity: int) -> None:
        current_quantity = self.inventory.get(item_id, 0)
        if not isinstance(quantity, (int, float)) or quantity <= 0:
            raise ValueError("Quantity must be a positive number.")
        if quantity > current_quantity:
            raise ValueError(f"Insufficient stock for item '{item_id}'.")
        old_value = current_quantity
        new_quantity = max(0, int(quantity) - current_quantity)
        self.inventory[item_id] = new_quantity
        if old_value != 0 and new_quantity < old_value:
            change_msg = f"Item '{item_id}' count reduced from {old_value} to {new_quantity}"
            self.logger.info(change_msg)
    def update_batch(self, items: List[tuple]) -> None:
        for item_id, qty in items:
            try:
                if isinstance(qty, float):
                    self.add_item(item_id, int(qty))
                else:
                    self.remove_item(item_id, int(qty))
            except ValueError as e:
                self.logger.error(f"Error processing {item_id}: {e}")
    def get_stock(self) -> Dict[str, int]:
        return dict(self.inventory)
if __name__ == '__main__':
    manager = InventoryManager()
    sample_operations = [
        ("Laptop", 10),
        ("Mouse", 50),
        ("Keyboard", 25),
        ("Monitor", 30),
        ("USB-Cable", 100)
    ]
    manager.update_batch(sample_operations)
    print("Current Inventory:")
    for item, count in sorted(manager.get_stock().items()):
        print(f"{item}: {count}")

import logging
from datetime import datetime
class InventoryManager:
    def __init__(self):
        self.inventory = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
    def add_item(self, item_id: str, quantity: int):
        current_quantity = self.inventory.get(item_id, 0)
        new_quantity = current_quantity + quantity
        change_amount = new_quantity - current_quantity
        if change_amount != 0:
            old_value = f"{item_id}: {current_quantity}"
            new_value = f"{item_id}: {new_quantity}"
            self.logger.info("Count changed: %s -> %s", old_value, new_value)
        self.inventory[item_id] = new_quantity
    def update_batch(self, item_ids: list[str], quantities: dict):
        for item_id in item_ids:
            if item_id not in quantities:
                continue
            current_quantity = self.inventory.get(item_id, 0)
            new_quantity = current_quantity + quantities[item_id]
            change_amount = new_quantity - current_quantity
            if change_amount != 0:
                old_value = f"{item_id}: {current_quantity}"
                new_value = f"{item_id}: {new_quantity}"
                self.logger.info("Count changed: %s -> %s", old_value, new_value)
            self.inventory[item_id] = new_quantity
    def get_total_items(self):
        return sum(self.inventory.values())
if __name__ == '__main__':
    manager = InventoryManager()
    manager.add_item('A001', 50)
    manager.update_batch(['B002'], {'B002': 30})
    print(f"Total items: {manager.get_total_items()}")

import logging
from datetime import datetime
from typing import Dict, List, Optional
class InventoryManager:
    def __init__(self) -> None:
        self.inventory: Dict[str, int] = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
    def add_item(self, item_id: str, quantity: int) -> None:
        if not isinstance(quantity, int):
            raise ValueError("Quantity must be an integer.")
        current_count = self.inventory.get(item_id, 0)
        new_quantity = current_count + quantity
        if new_quantity < 0:
            raise ValueError(f"Cannot reduce inventory of {item_id} below zero.")
        old_value = current_count
        self.inventory[item_id] = new_quantity
        change_message = (f"{datetime.now().isoformat()} - "
                         f"Inventory update for '{item_id}'. "
                         f"Old count: {old_value}, New count: {new_quantity}.")
        if old_value != 0 and quantity > 0:
            self.logger.info(change_message)
        elif new_quantity == 0:
            self.logger.warning(f"{datetime.now().isoformat()} - "
                              f"Inventory cleared for '{item_id}'.")
    def update_batch(self, item_ids: List[str], quantities: Dict[str, int]) -> None:
        if not isinstance(item_ids, list) or len(item_ids) != len(quantities):
            raise ValueError("Item IDs and quantities must be lists of the same length.")
        for i in range(len(item_ids)):
            item_id = item_ids[i]
            quantity = quantities.get(item_id, 0)
            if not isinstance(quantity, int):
                raise ValueError(f"Quantity for {item_id} is not an integer.")
            current_count = self.inventory.get(item_id, 0)
            try:
                old_value = current_count
                new_quantity = current_count + quantity
                if new_quantity < 0:
                    raise ValueError(
                        f"Cannot reduce inventory of '{item_id}' below zero. "
                        f"Requested change would result in negative stock."
                    )
                self.inventory[item_id] = new_quantity
                timestamp_str = datetime.now().isoformat()
                if old_value != 0 and quantity > 0:
                    msg = (f"{timestamp_str} - Inventory update for '{item_id}'. "
                           f"Old count: {old_value}, New count: {new_quantity}.")
                    self.logger.info(msg)
                elif new_quantity == 0:
                    msg = (f"{timestamp_str} - Inventory cleared for '{item_id}'.")
                    self.logger.warning(msg)
            except ValueError as ve:
                raise ve from None
