    print(f"Banana count: {inventory.get_current_count('banana')}")
    result = inventory.decrement("apple", 2)
    if result:
        print(f"After decrement, Apple count: {inventory.get_current_count('apple')}")
    else:
        print("Insufficient stock.")
    inventory.reset_inventory()
    print("Inventory reset successfully.")

