    def increment(self, amount: int = 1) -> None:
        with self._lock:
            self._count += amount
    def decrement(self, amount: int = 1) -> None:
        if amount <= 0:
            raise ValueError("Amount must be positive")
        with self._lock:
            self._count -= amount
    def get_count(self) -> int:
        with self._lock:
            return self._count
    def reset_inventory(self) -> None:
        with self._lock:
            self._count = 0
