import csv
import json
class DuplicateKeyError(Exception):
    pass
def parse_and_validate_config(data_source: str) -> dict:
    config = {}
    try:
        if data_source.endswith('.csv'):
            with open(data_source, 'r') as f:
                reader = csv.DictReader(f)
                for row in reader:
                    key_value_pairs = [k.strip() for k, v in zip(row.keys(), row.values())]
                    config.update(key_value_pairs)
        elif data_source.endswith('.json'):
            with open(data_source, 'r') as f:
                json_data = json.load(f)
                if isinstance(json_data, dict):
                    keys_to_check = list(json_data.keys()) + [k for k in range(len(json_data)) if not any(k == str(i) for i in range(10))]
                    config.update(json_data)
        else:
            raise ValueError("Unsupported file format")
    except FileNotFoundError as e:
        print(f"Error reading {data_source}: {e}")
    seen_keys = set()
    unique_config = {}
    for key, value in config.items():
        if not isinstance(key, str):
            continue
        normalized_key = key.strip().lower()
        if normalized_key in seen_keys:
            raise DuplicateKeyError(f"Duplicate key detected: '{key}'")
        unique_config[normalized_key] = value
        seen_keys.add(normalized_key)
    return unique_config
if __name__ == '__main__':
    config_data = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "debug_mode": True,
        "timeout": 30
    }
    try:
        result_config = parse_and_validate_config("config.json")
        print(f"Configuration loaded successfully:")
        for k, v in result_config.items():
            print(f"{k}: {v}")
    except DuplicateKeyError as e:
        print(e)

from dataclasses import dataclass, field
from typing import Dict, List
@dataclass(frozen=True)
class InventoryItem:
    id: str
    name: str
    quantity: int = 0
    def add_quantity(self, amount: int) -> None:
        if amount < 0:
            raise ValueError("Quantity cannot be decreased via this method.")
        self.quantity += amount
    def remove_quantity(self, amount: int) -> None:
        if amount < 0:
            raise ValueError("Quantity cannot be decreased via this method.")
        self.quantity -= amount
    def __repr__(self) -> str:
        return f"InventoryItem(id={self.id}, name='{self.name}', quantity={self.quantity})"
class InventoryManager:
    def __init__(self, initial_items: List[Dict[str, any]] = None) -> None:
        self._items: Dict[str, InventoryItem] = {}
        if initial_items is not None:
            for item_data in initial_items:
                qty = item_data.get('quantity', 0)
                self.add_item(item_data['id'], item_data['name'], qty)
    def add_item(self, id: str, name: str, quantity: int = 0) -> InventoryItem:
        self._items[id] = InventoryItem(id=id, name=name, quantity=quantity)
        return self._items[id]
    def get_item(self, id: str) -> InventoryItem | None:
        return self._items.get(id)
    def update_quantity(self, id: str, amount: int = 0) -> bool:
        item = self.get_item(id)
        if item is None:
            return False
        try:
            new_qty = item.quantity + amount
            if new_qty < 0:
                raise ValueError(f"Cannot reduce stock of '{item.name}' to negative value.")
            item.quantity = new_qty
            return True
        except Exception as e:
            print(f"Error updating quantity for {id}: {e}")
            return False
    def get_all_items(self) -> List[InventoryItem]:
        return list(self._items.values())
if __name__ == '__main__':
    initial_stock = [
        {'id': 'ITEM-001', 'name': 'Widget A'},
        {'id': 'ITEM-002', 'name': 'Gadget B', 'quantity': 50},
        {'id': 'ITEM-003', 'name': 'Tool C'}
    ]
    manager = InventoryManager(initial_stock)
    print("Initial State:")
    for item in manager.get_all_items():
        print(f"  {item}")
    widget_a_id = 'ITEM-001'
    manager.update_quantity(widget_a_id, amount=25)
    gadget_b_id = 'ITEM-002'
    manager.update_quantity(gadget_b_id, amount=-5)
    print("\nUpdated State:")
    for item in manager.get_all_items():
        print(f"  {item}")
    retrieved_item = manager.get_item('ITEM-003')
    if retrieved_item:
        print(f"\nRetrieved Item Details - ID: {retrieved_item.id}, Name: {retrieved_item.name}, Count: {retrieved_item.quantity}")

from dataclasses import dataclass
from typing import List, Dict
@dataclass(frozen=True)
class InventoryItem:
    id: str
    name: str
    quantity: int = 0
    def add_stock(self, amount: int) -> "InventoryItem":
        return InventoryItem(id=self.id, name=self.name, quantity=quantity + amount if (quantity := self.quantity) else 0)
    def remove_stock(self, amount: int) -> "InventoryItem":
        new_quantity = max(0, self.quantity - amount)
        return InventoryItem(id=self.id, name=self.name, quantity=new_quantity)
def calculate_total_value(items: List[InventoryItem], price_map: Dict[str, float]) -> float:
    return round(sum(item.quantity * price_map.get(item.id, 0) for item in items), 2)
def generate_inventory_report(items: List[InventoryItem]) -> Dict[str, int]:
    report = {}
    for item in items:
        if len(item.name) > 5:
            cat = "Electronics"
        else:
            cat = "General Goods"
        current_count = report.get(cat, 0) + item.quantity
        report[cat] = current_count
    return report
if __name__ == '__main__':
    items_data = [
        InventoryItem(id="ITEM-001", name="Widget A"),
        InventoryItem(id="ITEM-002", name="Gadget B"),
        InventoryItem(id="ITEM-003", name="Super Widget X")
    ]
    price_map = {
        "ITEM-001": 5.99,
        "ITEM-002": 12.50,
        "ITEM-003": 45.00
    }
    final_items = [item for item in items_data] 
    total_val = calculate_total_value(final_items, price_map)
    print(f"Total Inventory Value: ${total_val:.2f}")
    report = generate_inventory_report(items_data)
    print("Inventory Report by Category:", report)
    modified_item = items_data[0].add_stock(10)
    removed_item = items_data[2].remove_stock(5)
    print(f"Modified Item Stock: {modified_item.quantity}")
    print(f"Removed Item Stock: {removed_item.quantity}")

from dataclasses import dataclass
from typing import List, Dict
@dataclass(frozen=True)
class InventoryItem:
    id: str
    name: str
    quantity: int
    def is_available(self, required_amount: int) -> bool:
        return self.quantity >= required_amount
class InventoryManager:
    def __init__(self) -> None:
        self._items: List[InventoryItem] = []
    def add_item(self, item_id: str, name: str, quantity: int) -> InventoryItem:
        if quantity < 0:
            raise ValueError("Quantity cannot be negative.")
        new_item = InventoryItem(id=item_id, name=name, quantity=quantity)
        self._items.append(new_item)
        return new_item
    def get_items(self) -> List[InventoryItem]:
        return self._items.copy()
    def update_quantity(self, item_id: str, delta: int) -> bool:
        for i, item in enumerate(self._items):
            if item.id == item_id:
                self._items[i] = InventoryItem(id=item.id, name=item.name, quantity=delta + item.quantity)
                return True
        raise ValueError(f"Item with ID '{item_id}' not found.")
    def check_stock_availability(self, required_amount: int) -> Dict[str, bool]:
        return {item.id: item.is_available(required_amount) for item in self._items}
if __name__ == '__main__':
    manager = InventoryManager()
    manager.add_item("ITEM-001", "Laptop Pro X1", 50)
    manager.add_item("ITEM-002", "Wireless Mouse M3", 120)
    manager.add_item("ITEM-003", "USB-C Hub Adapter", 85)
    print(manager.check_stock_availability(60))
    manager.update_quantity("ITEM-002", 40)
    current_items = manager.get_items()
    for item in current_items:
        print(f"{item.name}: {item.quantity} available")

from dataclasses import dataclass
from typing import List
@dataclass
class InventoryItem:
    id: int
    name: str
    quantity: int
    def add_quantity(self, amount: int) -> None:
        if amount < 0:
            raise ValueError("Quantity cannot be decreased using this method.")
        self.quantity += amount
    def remove_quantity(self, amount: int) -> None:
        if amount < 0:
            raise ValueError("Amount cannot be negative.")
        if self.quantity - amount < 0:
            raise ValueError(f"Cannot remove {amount} units from item '{self.name}'. Only {self.quantity} available.")
        self.quantity -= amount
class InventoryManager:
    def __init__(self) -> None:
        self.items: List[InventoryItem] = []
    def add_item(self, item_id: int, name: str, quantity: int) -> InventoryItem | None:
        if quantity < 0:
            return None
        for item in self.items:
            if item.id == item_id:
                return item
        new_item = InventoryItem(id=item_id, name=name, quantity=quantity)
        self.items.append(new_item)
        return new_item
    def get_total_inventory(self) -> int:
        return sum(item.quantity for item in self.items)
if __name__ == '__main__':
