        (5, "banana"),
        {"orange": 3.5, None: "invalid"},
        ("cherry", 20),
        ("grape", -5)
    ]
    constructed_dict = build_dict_from_iterable(sample_data)
    print(f"Constructed Dictionary: {constructed_dict}")

