import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
class ConfigLoader:
    def __init__(self):
        self.configs_cache: Dict[str, Dict] = {}
    def load_from_file(self, file_path: str) -> Optional[Dict]:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                logger.error(f"Configuration in {file_path} is not a dictionary.")
                return None
            self.configs_cache[file_path] = data
            logger.info(f"Successfully loaded configuration from {file_path}")
            return data
        except FileNotFoundError:
            logger.warning(f"File {file_path} not found. Attempting fallback...")
            return None
        except json.JSONDecodeError as e:
            logger.error(f"Invalid JSON in {file_path}: {e}. Fallback triggered.")
            return None
    def get_config(self, file_paths: list[str], default_data: Optional[Dict] = None) -> Dict:
        for path in reversed(file_paths):                                       
            if path not in self.configs_cache and Path(path).exists():
                config = self.load_from_file(str(Path(path)))
                if config is not None:
                    return config
        logger.warning("No valid configuration found. Using default.")
        return default_data or {}
if __name__ == '__main__':
    loader = ConfigLoader()
    primary_config_path = "config_primary.json"
    fallback_config_path = "config_backup.json"
    defaults = {
        "app_name": "DefaultApp",
        "debug_mode": False,
        "max_retries": 3
    }
    final_config: Dict[str, Any] = loader.get_config([primary_config_path, fallback_config_path], defaults)
    print(f"Loaded configuration for {final_config.get('app_name', 'Unknown')}")
    logger.info("Configuration loaded successfully.")

import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional
def setup_logging(config_path: str) -> None:
    log_dir = Path("logs") / "config"
    log_dir.mkdir(parents=True, exist_ok=True)
    handler = logging.FileHandler(log_dir / f"{Path(config_path).stem}.log", mode="a")
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
    logger = logging.getLogger()
    logger.setLevel(logging.INFO)
    logger.addHandler(handler)
def load_config_file(path: str, fallback_value: Any = None) -> Dict[str, Any]:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Config file {path} not found. Using default values.")
        if fallback_value is None:
            raise ValueError("No config provided and no fallback defined")
        return fallback_value.copy()
def create_dictionary_from_config(config_path: str, defaults: Dict[str, Any]) -> Dict[str, Any]:
    setup_logging(config_path)
    logger = logging.getLogger(__name__)
    try:
        config_data = load_config_file(config_path, {})
        merged_dict = defaults.copy()
        for key in config_data.keys():
            if key not in merged_dict and isinstance(config_data[key], dict):
                nested_key_list = list(config_data[key].keys())
                logger.info(f"Found {len(nested_key_list)} keys: {nested_key_list}")
                for k, v in config_data[key].items():
                    if key not in merged_dict or isinstance(merged_dict.get(key), dict):
                        nested = merged_dict.setdefault(key, {})
                        if isinstance(v, (dict, list)):
                            logger.debug(f"Key '{k}' has type {type(v).__name__}")
                            for nk, nv in v.items():
                                if not isinstance(nv, str) and len(str(nv)) > 0:
                                    nested[nk] = json.dumps(nv)
                        else:
                            logger.debug(f"Key '{key}' has type {type(v).__name__}")
                            for nk, nv in v.items():
                                if not isinstance(nv, str):
                                    nested[nk] = json.dumps(nv)
        return merged_dict
    except Exception as e:
        logger.error(f"Error loading configuration from {config_path}: {str(e)}")
        raise
if __name__ == '__main__':
    sample_config = {"app": {"host": "localhost", "port": 8080}}
    defaults = {
        "database": {"driver": "sqlite3"},
        "cache": {"enabled": True},
        "logging": {"level": "INFO"}
    }
    result_dict = create_dictionary_from_config("config.json", defaults)
    print(json.dumps(result_dict, indent=2))

import json
import logging
from pathlib import Path
from typing import Any, Dict, Optional
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
def load_config_file(filepath: str) -> Optional[Dict[str, Any]]:
    try:
        with open(Path(filepath), "r", encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        logger.warning(f"Configuration file not found at {filepath}. Fallback to defaults.")
        return None
    except json.JSONDecodeError as e:
        logger.error(f"Failed to parse JSON in {filepath}: {e}")
        return None
def create_dictionary(
    config_path: str,
    default_config: Dict[str, Any],
) -> Dict[str, Any]:
    loaded = load_config_file(config_path)
    if not loaded or (loaded is None and Path(config_path).exists()):
        logger.warning("Using fallback configuration.")
        return default_config.copy()
    final_config = default_config.copy()
    for key in list(final_config.keys()):
        try:
            new_value = loaded[key]
            if isinstance(new_value, dict):
                nested_keys = [k for k in final_config.get(key, {}) if not callable(getattr(type(None), f'{key}', None))]                                                           
                if any(isinstance(final_config[key][k], (dict, list)) and loaded[key].get(k) is not None for k in nested_keys):
                    new_value = final_config.get(key, {})
            elif isinstance(new_value, dict):
                pass
        except Exception as e:
            logger.error(f"Error merging config at key {key}: {e}")
    if loaded and Path(config_path).exists():
        for key in list(final_config.keys()):
            new_val = loaded.get(key)
            try:
                final_config[key] = new_val
            except Exception as e:
                logger.error(f"Error updating config at key {key}: {e}")
    return final_config
if __name__ == '__main__':
    default_settings = {"database": "localhost", "port": 5432, "timeout": 10}
    result_dict = create_dictionary("config.json", default_settings)
    print(json.dumps(result_dict))

import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
class ConfigLoader:
    def __init__(self, config_path: str):
        self.config_path = Path(config_path)
    def load(self) -> Dict[str, Any]:
        if not self.config_path.exists():
            logger.warning(f"Configuration file {self.config_path} not found. Using defaults.")
            return {}
        try:
            with open(self.config_path, 'r') as f:
                config = json.load(f)
            logger.info("Successfully loaded configuration from external source")
            return config
        except json.JSONDecodeError as e:
            logger.error(f"Failed to parse JSON in {self.config_path}: {e}")
            self._apply_defaults()
    def _apply_defaults(self):
        defaults = {"timeout": 30, "retries": 3}
        for key, value in defaults.items():
            if key not in self.load_config_data():
                logger.info(f"Applying default value for {key}: {value}")
    def load_config_data(self) -> Dict[str, Any]:
        return {}
if __name__ == '__main__':
    loader = ConfigLoader('config.json')
    config_dict: Dict[str, Any] = loader.load()
    if 'timeout' in config_dict and not isinstance(config_dict['timeout'], int):
        logger.warning("Invalid timeout type detected. Converting to integer.")
        config_dict['timeout'] = 30
    print(f"Loaded configuration dictionary:")
    for key, value in config_dict.items():
        if 'timeout' in str(key).lower() or 'retries' in str(key).lower():
            logger.info(f"{key}: {value}")

import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional
def setup_logging(log_file: str = "app.log", log_level: int = 20) -> None:
    logger = logging.getLogger("config_loader")
    handler = logging.FileHandler(log_file)
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
