def load_json_config(file_path: str, fallback_value: Any = None) -> Dict[str, Any]:
    config = {}
    try:
        with open(Path(file_path), "r") as f:
            content = json.load(f)
            if isinstance(content, dict):
                return content
            else:
                raise ValueError("Configuration must be a JSON object.")
    except FileNotFoundError:
        logging.warning(f"File {file_path} not found. Using fallback value.")
        config = fallback_value.copy() if isinstance(fallback_value, dict) else {}
    except json.JSONDecodeError as e:
        error_msg = f"Invalid JSON in {file_path}: {e}"
        logging.error(error_msg)
        config = fallback_value.copy() if isinstance(fallback_value, dict) else {}
    return config
def create_dictionary_from_config(
    primary_file: str,
    secondary_files: list[str],
    default_fallback: Dict[str, Any] | None = None,
    log_level: int = 20,
    log_file: str = "config_loader.log",
) -> Dict[str, Any]:
    setup_logging(log_file=log_file, log_level=log_level)
    logger = logging.getLogger("config_loader")
    config_dict = {}
    if primary_file and Path(primary_file).exists():
        try:
            with open(Path(primary_file), "r") as f:
                data = json.load(f)
                if isinstance(data, dict):
                    for key in default_fallback or {}:
                        if key not in config_dict:
                            config_dict[key] = default_fallback[key]
        except Exception as e:
            logger.error(f"Error loading primary file {primary_file}: {e}")
    else:
        logger.warning(f"Primary configuration file {primary_file} does not exist.")
    for idx, secondary in enumerate(secondary_files):
        try:
            with open(Path(secondary), "r") as f:
                data = json.load(f)
                if isinstance(data, dict):
                    for key in default_fallback or {}:
                        if key not in config_dict and key in data:
                            config_dict[key] = data[key]
        except Exception as e:
            logger.warning(f"Error loading secondary file {secondary}: {e}")
    return config_dict
if __name__ == '__main__':
    primary_file_path = "config_primary.json"
    secondary_files_list = ["config_secondary_1.json", "config_backup.json"]
    default_fallback_data: Dict[str, Any] = {"timeout": 30, "retries": 3}
    final_config = create_dictionary_from_config(
        primary_file=primary_file_path,
        secondary_files=secondary_files_list,
        default_fallback=default_fallback_data,
        log_level=logging.INFO,
        log_file="production.log",
    )
    print("Final Configuration:")
    for key in final_config:
        if isinstance(final_config[key], int):
            print(f"{key}: {final_config[key]}")

import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional
def setup_logging(config: Dict[str, Any]) -> None:
    log_level = getattr(logging, config.get("logging", {}).get("level", "INFO"), logging.INFO)
    handler = logging.StreamHandler()
    formatter = logging.Formatter(
        "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
    )
    logger = logging.getLogger("config_loader")
    logger.setLevel(log_level)
    handler.setFormatter(formatter)
    logger.addHandler(handler)
def load_json_file(file_path: str, fallback_dict: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    if not Path(file_path).exists():
        return fallback_dict or {}
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            logging.info(f"Successfully loaded configuration from {file_path}")
            return data
    except (json.JSONDecodeError, IOError):
        if fallback_dict is not None:
            logging.warning(
                f"Failed to parse or read {file_path}, using fallback dictionary."
            )
            return fallback_dict
        else:
            raise
def create_dictionary_from_config(
    primary_file: str,
    secondary_files: list[str],
    default_values: Dict[str, Any] = None,
) -> Dict[str, Any]:
    logging.info("Starting configuration load process")
    result: Dict[str, Any] = {}
    if not Path(primary_file).exists():
        logging.warning(f"Primary config {primary_file} missing. Using default values.")
        result.update(default_values or {})
    else:
        loaded_data = load_json_file(primary_file, default_values)
        result.update(loaded_data)
    logging.info(f"Processing {len(secondary_files)} secondary configuration files.")
    for file_path in secondary_files:
        if not Path(file_path).exists():
            continue
        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            for key, value in data.items():
                if (key not in result and 
                    default_values is None or key in default_values):
                    logging.info(
                        f"Applying configuration from {file_path} for key '{key}'."
                    )
                    result[key] = value
        except Exception as e:
            logging.error(f"Error processing file {file_path}: {e}")
    return result
if __name__ == '__main__':
    primary_file = "/etc/config/app.json"
    secondary_files = ["/etc/config/override1.json", "/etc/config/override2.json"]
    default_dict: Dict[str, Any] = {
        "app_name": "MyApp",
        "debug_mode": False,
        "max_connections": 100
    }
    config_data = create_dictionary_from_config(
        primary_file=primary_file,
        secondary_files=secondary_files,
        default_values=default_dict
    )
    logging.info("Configuration loaded successfully.")
    print(json.dumps(config_data, indent=2))

import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
class ConfigLoader:
    def __init__(self):
        self.configs_cache: Dict[str, Dict] = {}
    def load_from_file(self, file_path: str) -> Optional[Dict]:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                logger.error(f"Configuration in {file_path} is not a dictionary.")
                return None
            self.configs_cache[file_path] = data
            logger.info(f"Successfully loaded configuration from {file_path}")
            return data
        except FileNotFoundError:
            logger.warning(f"File {file_path} not found. Attempting fallback...")
            return None
        except json.JSONDecodeError as e:
            logger.error(f"Invalid JSON in {file_path}: {e}. Fallback triggered.")
            return None
    def get_config(self, file_paths: list[str], default_data: Optional[Dict] = None) -> Dict:
        for path in reversed(file_paths):                                       
            if path not in self.configs_cache and Path(path).exists():
                config = self.load_from_file(str(Path(path)))
                if config is not None:
                    return config
        logger.warning("No valid configuration found. Using default.")
        return default_data or {}
if __name__ == '__main__':
    loader = ConfigLoader()
    primary_config_path = "config_primary.json"
    fallback_config_path = "config_fallback.json"
    defaults = {"app_name": "DefaultApp", "debug_mode": False}
    final_config: Dict[str, Any] = loader.get_config([primary_config_path, fallback_config_path], defaults)
    print(f"Loaded configuration for {final_config.get('app_name', 'Unknown')}")

import json
import logging
from pathlib import Path
from typing import Any, Dict, Optional
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
class ConfigLoader:
    def __init__(self, config_path: str):
        self.config_path = Path(config_path)
    def load(self) -> Dict[str, Any]:
        try:
            with open(self.config_path, 'r') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError("Configuration must be a JSON object")
            logger.info(f"Successfully loaded configuration from {self.config_path}")
            return data
        except FileNotFoundError:
            logger.warning(f"Config file '{self.config_path}' not found. Using defaults.")
            return self.get_defaults()
        except json.JSONDecodeError as e:
            logger.error(f"Failed to parse JSON in '{self.config_path}': {e}")
            raise
    def get_defaults(self) -> Dict[str, Any]:
        default_config = {
            "app_name": "ProductionApp",
            "debug_mode": False,
            "max_retries": 3,
            "timeout_seconds": 60
        }
        logger.info("Using default configuration values")
        return default_config
if __name__ == '__main__':
    loader = ConfigLoader('config.json')
    try:
        config_dict = loader.load()
        print(f"Loaded Configuration for {config_dict.get('app_name', 'Unknown')}")
        if not config_dict['debug_mode']:
            logger.info("Running in production mode with retries enabled.")
    except Exception as e:
        logger.critical(f"Configuration loading failed due to error: {e}")

