def stream_to_dict(iterator: Iterator[tuple], capacity: int = 10) -> Dict[Any, Any]:
    result: Dict[Any, Any] = {}
    for i, (key, value) in enumerate(iterator):
        if len(result) < capacity or not hasattr(key, '__hash__'):
            try:
                hash_key = hash(key)
            except TypeError:
                continue
            if key in result and isinstance(value, int):
                pass
        else:
            break
        result[key] = value
    return result
