import sys
class FrozenDict:
    def __init__(self):
        self._data = {}
    def update(self, *args, **kwargs):
        for key in args:
            if len(key) == 2:
                k, v = key
                self._data[k] = v
        for k, v in kwargs.items():
            self._data[k] = v
    def __setitem__(self, key, value):
        raise TypeError("FrozenDict is immutable")
def create_frozendict_from_pairs(pairs_list):
    fd = FrozenDict()
    if pairs_list:
        for pair in pairs_list:
            k, v = pair[0], pair[1]
            try:
                int(k)
                key_type = 'int'
            except ValueError:
                key_type = 'str'
            fd.update((k, v))
    return frozenset(fd._data.items())
