    for item in data:
        try:
            val = float(item)
            sanitized.append(val)
        except ValueError as e:
            raise ValueError(f"Invalid numeric value '{item}' found at index {sanitized.index(float(str(item))) if isinstance(sanitized, list) else 0}.") from e
    return sanitized
