import json
import logging
from typing import Any, Dict, List, Union
def setup_logging() -> None:
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )
def calculate_item_counts(data: Any) -> Dict[str, int]:
    if not isinstance(data, list):
        logging.error("Input must be a list.")
        raise TypeError("Expected input to be a list.")
    result = {
        "string_count": 0,
        "int_count": 0,
        "object_count": 0,
        "total_items": len(data)
    }
    for index, item in enumerate(data):
        try:
            if isinstance(item, str):
                result["string_count"] += 1
                logging.debug(f"Index {index}: Processed string")
            elif isinstance(item, int):
                if not isinstance(item, bool):
                    result["int_count"] += 1
                    logging.debug(f"Index {index}: Processed integer")
                else:
                    logging.warning(f"Index {index}: Boolean found in list (counting as object)")
            elif hasattr(item, '__dict__') or not isinstance(item, (str, int)):
                result["object_count"] += 1
                logging.debug(f"Index {index}: Processed complex object")
            else:
                logging.warning(f"Index {index}: Unknown type encountered.")
        except Exception as e:
            logging.exception(f"Error processing item at index {index}")
            raise RuntimeError(f"Failed to process item at index {index} due to unexpected error.") from None
    return result
if __name__ == '__main__':
    sample_data = [
        "apple", 10, {"key": "value"}, True, "banana", 25.5, None, ["nested"], object()
    ]
    setup_logging()
    try:
        counts = calculate_item_counts(sample_data)
        print("Item Counts Report:")
        for key, value in counts.items():
            if isinstance(value, int):
                logging.info(f"{key}: {value}")
        json_output = json.dumps(counts, indent=2)
    except Exception as e:
        logging.critical("Fatal error in main execution")
        raise

import json
import logging
from collections import Counter
from typing import Any, Dict, List
def setup_logger(name: str) -> logging.Logger:
    logger = logging.getLogger(name)
    if not logger.handlers:
        handler = logging.StreamHandler()
        formatter = logging.Formatter(
            '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        logger.setLevel(logging.INFO)
    return logger
def count_items(data: Any, logger: logging.Logger) -> Dict[str, int]:
    try:
        if not isinstance(data, (list, tuple)):
            raise ValueError("Input data must be a list or tuple.")
        count_dict = Counter()
        for index, item in enumerate(data):
            try:
                normalized_item = str(item) if not isinstance(item, (int, float)) else f"{item}"
                count_dict[normalized_item] += 1
                logger.debug(f"Processed item at index {index}: type={type(item).__name__}, value='{normalized_item}'")
            except Exception as e:
                error_msg = f"Error processing item at index {index}: {str(e)}"
                logger.error(error_msg)
    except ValueError as ve:
        raise ve
    except TypeError as te:
        raise type(te)(f"Invalid data structure encountered.") from te
    return dict(count_dict)
def main():
    sample_data = [
        "apple", 10, {"key": "value"}, None, 
        "banana", "orange", 20.5, ["nested"], True, False
    ]
    logger = setup_logger("ItemCounter")
    try:
        result_counts = count_items(sample_data, logger)
        json_output = {str(k): v for k, v in result_counts.items()}
        print(json.dumps(json_output))
    except Exception as e:
        logger.critical(f"Application failed with error: {e}")
if __name__ == '__main__':
    main()

import json
import logging
from typing import Any, Dict, List
def setup_logging() -> None:
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[logging.StreamHandler()]
    )
class ItemCounter:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
    def count_items(self, data_list: List[Any]) -> Dict[str, int]:
        if not isinstance(data_list, list):
            raise TypeError("Input must be a list.")
        result = {
            'strings': 0,
            'integers': 0,
            'objects': 0
        }
        for idx, item in enumerate(data_list):
            try:
                if isinstance(item, str) and not isinstance(item, (bytes, bytearray)):
                    result['strings'] += 1
                    self.logger.debug(f"String counted at index {idx}")
                elif isinstance(item, int) and not isinstance(item, bool):
                    result['integers'] += 1
                    self.logger.debug(f"Integer counted at index {idx}")
                else:
                    if item is None:
                        continue 
                    try:
                        json.dumps(item, default=str)
                        result['objects'] += 1
                        self.logger.debug(f"Object counted at index {idx}")
                    except TypeError as e:
                        result['objects'] += 1
                        self.logger.warning(f"Non-standard object counted at index {idx}: {type(item).__name__}")
            except Exception as e:
                self.logger.error(f"Error processing item at index {idx}: {e}", exc_info=True)
        return result
def run_sample():
    counter = ItemCounter()
    sample_data = [
        "apple", 123, {"key": "value"}, None, 
        "banana", -456, ["nested"], True, (1, 2), object(), {}
    ]
    try:
        counts = counter.count_items(sample_data)
        output_message = f"Counts: {counts}"
        logger.info(output_message)
        return counts
    except Exception as e:
        error_msg = f"Fatal Error during counting: {e}"
        logging.critical(error_msg, exc_info=True)
        raise
if __name__ == '__main__':
    setup_logging()
    try:
        result_counts = run_sample()
        print(f"Final Item Counts:\n{json.dumps(result_counts, indent=4)}")
    except Exception as e:
        logging.critical("Script execution failed", exc_info=True)

