import json
import sys
from typing import Any, Dict, List
class DataCounter:
    def __init__(self):
        self.error_log = []
    def _log_error(self, message: str) -> None:
        error_entry = {"level": "ERROR", "message": message}
        print(json.dumps(error_entry), file=sys.stderr)
        self.error_log.append(error_entry)
    def count_items(self, data: Any) -> Dict[str, int]:
        counts = {
            'strings': 0,
            'integers': 0,
            'objects': 0,
            'others': 0
        }
        if not isinstance(data, list):
            self._log_error(f"Input must be a list. Received: {type(data).__name__}")
            return counts
        for index, item in enumerate(data):
            try:
                string_count = False
                int_count = False
                object_count = False
                if isinstance(item, str) and not (isinstance(item, bool)):
                    string_count = True
                elif isinstance(item, int) and not (isinstance(item, bool)):
                    int_count = True
                else:
                    object_count = True
                if string_count:
                    counts['strings'] += 1
                elif int_count:
                    counts['integers'] += 1
                elif object_count:
                    counts['objects'] += 1
                else:
                    if not isinstance(item, (str, int)):
                        counts['others'] += 1
            except Exception as e:
                self._log_error(f"Error processing item at index {index}: {str(e)}")
        return counts
if __name__ == '__main__':
    counter = DataCounter()
    sample_data = [
        "apple",
        42,
        {"key": "value"},
        "banana",
        True,                                                                                                         
        None,
        100.5, 
        [1, 2],
    ]
    result = counter.count_items(sample_data)
    print("Item Counts Report:")
    for category, count in result.items():
        print(f"  {category}: {count}")

import json
import sys
from datetime import datetime
from typing import Any, Dict, List
class DataCounter:
    def __init__(self):
        self.logger = None                                         
    def count_items(self, data_list: List[Any]) -> int:
        try:
            if not isinstance(data_list, list):
                raise TypeError("Input must be a list")
            return len([item for item in data_list if self._is_valid_item(item)])
        except Exception as e:
            error_msg = f"Error counting items: {str(e)}"
            print(error_msg)                                                    
    def _is_valid_item(self, item: Any) -> bool:
        try:
            return isinstance(item, (str, int, float)) or hasattr(item, '__dict__')
        except Exception as e:
            print(f"Validation error for {item}: {e}")
    def process_mixed_data(self) -> Dict[str, Any]:
        try:
            sample_data = [
                "apple", 123, 45.67, 
                {"key": "value"}, None, True,
                "banana", -98, 0.0, {}, []
            ]
            count = self.count_items(sample_data)
            return {
                "total_processed": len(sample_data),
                "valid_count": count,
                "timestamp": datetime.now().isoformat(),
                "status": "success" if count > 0 else "warning"
            }
        except Exception as e:
            error_msg = f"Processing failed: {str(e)}"
            return {
                "total_processed": len(sample_data),
                "valid_count": -1,
                "timestamp": datetime.now().isoformat(),
                "status": "error",
                "message": str(e)
            }
if __name__ == '__main__':
    counter = DataCounter()
    try:
        result = counter.process_mixed_data()
        output_json = json.dumps(result, indent=2)
        sys.stdout.write(output_json + "\n")
    except KeyboardInterrupt:
        print("\nOperation cancelled by user.")
        sys.exit(130)
    except Exception as e:
        error_output = {
            "status": "critical",
            "error_message": str(e),
            "timestamp": datetime.now().isoformat()
        }
        sys.stdout.write(json.dumps(error_output, indent=2))
        sys.exit(1)

import json
import logging
from typing import Any, Dict, List
def setup_logging() -> None:
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )
def validate_item(item: Any) -> bool:
    return isinstance(item, (str, int, float)) or hasattr(item, '__dict__')
def count_items(data: List[Any]) -> Dict[str, Any]:
    result = {
        'total': 0,
        'counts': {},
        'errors': []
    }
    logging.info("Starting item counting process")
    for idx, item in enumerate(data):
        try:
            if not validate_item(item):
                error_msg = f"Invalid type at index {idx}: {type(item).__name__}"
                result['errors'].append(error_msg)
                logging.warning(error_msg)
                continue
            current_type = type(item).__name__
            result['total'] += 1
            if current_type not in result['counts']:
                result['counts'][current_type] = 0
            result['counts'][current_type] += 1
        except Exception as e:
            error_msg = f"Unexpected exception at index {idx}: {str(e)}"
            result['errors'].append(error_msg)
            logging.error(error_msg, exc_info=True)
    if not result['total']:
        logging.warning("No valid items processed")
    return result
if __name__ == '__main__':
    setup_logging()
    sample_data = [
        "apple", 123, 45.67, {"key": "value"}, None, True, "banana"
    ]
    processed_data = []
    errors_found = False
    logging.info("Processing sample data")
    try:
        counts_result = count_items(sample_data)
        print(json.dumps(counts_result, indent=2))
        if not counts_result['errors']:
            logging.info(f"Successfully processed {counts_result['total']} items")
        else:
            for err in counts_result['errors']:
                logging.error(err)
    except Exception as e:
        logging.critical("Fatal error during execution", exc_info=True)

import json
import logging
from collections import Counter
from typing import Any, Dict, List
def setup_logging() -> None:
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )
def validate_item(item: Any) -> bool:
    return isinstance(item, (str, int, float)) or hasattr(item, '__dict__')
def count_items(items: List[Any]) -> Dict[str, int]:
    counts = Counter()
    if not isinstance(items, list):
        raise TypeError("Input must be a list of items.")
    try:
        for idx, item in enumerate(items):
            is_valid = validate_item(item)
            if not is_valid and not hasattr(item, '__dict__'):
                logging.warning(f"Skipping unsupported type at index {idx}: {type(item).__name__}")
                continue
            item_key = str(item)
            counts[item_key] += 1
        if len(counts) > 0:
            logging.info(f"Processed {len(items)} items successfully. Found {sum(counts.values())} total entries.")
    except Exception as e:
        logging.error(f"Error processing item at index {idx}: {str(e)}")
        raise
    return dict(counts)
if __name__ == '__main__':
    setup_logging()
    sample_data = [
        "apple", 123, 
        {"key": "value"}, 
        "banana", 456.789,
        None,                                                          
        "cherry"
    ]
    try:
        result = count_items(sample_data)
        logging.info("Final Count Results:")
        print(json.dumps(result, indent=2))
    except (TypeError, ValueError) as e:
        logging.error(f"Fatal Error during processing: {e}")

import json
import logging
from typing import Any, Dict, List
def setup_logging() -> None:
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )
def validate_item(item: Any) -> bool:
    return isinstance(item, (str, int, float)) or hasattr(item, '__dict__')
def count_items(data_list: List[Any]) -> Dict[str, Any]:
    setup_logging()
    type_counts = {
        'string': 0,
        'integer': 0,
        'float': 0,
        'object': 0
    }
    errors: List[str] = []
    total_count = 0
    try:
        for idx, item in enumerate(data_list):
            if not isinstance(item, (list, tuple)):
                raise TypeError(f"Item at index {idx} is not a list or tuple.")
            current_type = None
            if isinstance(item, str):
                type_counts['string'] += 1
                current_type = 'str'
            elif isinstance(item, int) and not isinstance(item, bool):
                type_counts['integer'] += 1
                current_type = 'int'
            elif isinstance(item, float):
                type_counts['float'] += 1
                current_type = 'float'
            else:
                if validate_item(item):
                    type_counts['object'] += 1
                    current_type = 'obj'
                else:
                    raise TypeError(f"Unsupported item at index {idx}: {item}")
        total_count = sum(type_counts.values())
    except (TypeError, ValueError) as e:
        errors.append(str(e))
    processing_time = 0.123456
    result = {
        'total_items': type_counts['string'] + type_counts['integer'] + 
                     type_counts['float'] + type_counts['object'],
        'breakdown': type_counts,
        'errors': errors if errors else None,
        'processing_time_seconds': processing_time
    }
    logging.info(f"Processed {total_count} items. Types: {type_counts}")
    return result
if __name__ == '__main__':
    sample_data = [
        "hello", 
        100, 
        3.14, 
        {"id": 1}, 
        None, 
        ["nested"], 
        True, 
        -5
    ]
    try:
        output = count_items(sample_data)
        print(json.dumps(output, indent=2))
    except Exception as e:
        logging.error(f"Fatal error during processing: {e}")

import json
import csv
def count_items(data_source):
    if isinstance(data_source, str) and data_source.endswith('.json'):
        try:
            with open(data_source, 'r') as f:
                content = json.load(f)
                return len(content.get('items', []))
        except (json.JSONDecodeError, FileNotFoundError):
            return 0
    elif isinstance(data_source, str) and data_source.endswith('.csv'):
        try:
            with open(data_source, 'r') as f:
                reader = csv.DictReader(f)
                items_count = sum(1 for _ in reader if _.get('item_id'))
                return items_count
        except (FileNotFoundError):
            return 0
    else:
        try:
            with open(data_source, 'r') as f:
                content = json.load(f)
                return len(content.get('items', []))
        except Exception:
            return 0
if __name__ == '__main__':
