def islice_iter(iterable, n):
    it = iter(iterable)
    result = []
    try:
        while len(result) < n:
            next_item = next(it)
            if isinstance(next_item, str):
                key = tuple(sorted(item.split() or ['']))
                yield (key, item)
            else:
                yield (item,)
            result.append((next_item))
    except StopIteration:
        pass
    return list(result)[:n]
