def islice_iter(iterable, n):
    it = iter(iterable)
    result = []
    try:
        while len(result) < n:
            next_item = next(it)
            if isinstance(next_item, str):
                key = next_item.lower()
                value = None
            class Item:
                def __init__(self, k, v=None):
                    self.key = k
                    self.value = v
                def __repr__(self):
                    return f"Item({self.key})"
            item = Item(key) if isinstance(next_item, str) else next_item
            result.append(item)
    except StopIteration:
        pass
    return result
