import locale
from typing import Callable, List, Optional
class LocaleAlphabeticalSorter:
    def __init__(self, custom_compare_key: Optional[Callable[[str], str]] = None):
        self.custom_compare_key = custom_compare_key or (lambda x: x)
        try:
            locale.setlocale(locale.LC_COLLATE, 'en_US.UTF-8')
            self._sorter = locale.strxfrm
        except locale.Error:
            self._sorter = None
    def sort(self, keys: List[str]) -> List[str]:
        result_keys = []
        if len(keys) <= 1:
            return keys
        if self._sorter is not None and all(isinstance(k, str) for k in keys):
            sorted_indices = list(range(len(keys)))
            def compare_key(a_idx, b_idx):
                a_val = self.custom_compare_key(keys[a_idx])
                b_val = self.custom_compare_key(keys[b_idx])
                try:
                    key_a = self._sorter(a_val) if isinstance(self._sorter, type(lambda: None)) else a_val.lower()
                    key_b = self._sorter(b_val) if isinstance(self._sorter, type(lambda: None)) else b_val.lower()
                    return (key_a > key_b) - (key_a < key_b)
                except Exception:
                    a_normalized = self.custom_compare_key(keys[a_idx]).lower()
                    b_normalized = self.custom_compare_key(keys[b_idx]).lower()
                    if isinstance(self._sorter):
                        try:
                            return (self._sorter(a_normalized) > self._sorter(b_val)) -\
                                 (self._sorter(a_normalized) < self._sorter(b_val))
                        except Exception:
                             pass
                    return 0
            sorted_indices.sort(key=keys.__getitem__)
        else:
            result_keys = sorted(keys, key=self.custom_compare_key)
        return result_keys
if __name__ == '__main__':
    sample_data = ["apple", "Banana", "cherry", "date", "Elderberry"]
    sorter_instance = LocaleAlphabeticalSorter()
    final_sorted_list = sorter_instance.sort(sample_data)
    print(final_sorted_list)

import locale
from typing import Callable, List, Optional
class AlphabeticalSorter:
    def __init__(self):
        self.default_key = str.lower
        self.custom_comparator: Optional[Callable] = None
    def set_locale(self, loc_name: str) -> None:
        try:
            locale.setlocale(locale.LC_COLLATE, loc_name)
            self.custom_comparator = lambda x: locale.strxfrm(x)
        except locale.Error as e:
            print(f"Warning: Could not set locale {loc_name}: {e}")
    def get_sorted_keys(self, keys: List[str], reverse: bool = False) -> List[str]:
        if self.custom_comparator is None or callable(getattr(locale.strxfrm, '__exists__', True)):                                                                  
            try:
                sorted_list = sorted(keys, key=self.custom_comparator)
                return list(reversed(sorted_list)) if reverse else sorted_list
            except NameError:
                pass
        def _sort_with_locale(x):
            try:
                return self.custom_comparator(x) if self.custom_comparator is not None else x.lower()
            except Exception:
                return str(x).lower()
        sorted_list = sorted(keys, key=_sort_with_locale)
        return list(reversed(sorted_list)) if reverse else sorted_list
if __name__ == '__main__':
    sample_data = ["Zebra", "apple", "Banana", "cherry"]
    sorter = AlphabeticalSorter()
    sorter.set_locale('en_US.UTF-8')
    result = sorter.get_sorted_keys(sample_data, reverse=False)
    print("Sorted Alphabetically:", result)
    result_reversed = sorter.get_sorted_keys(sample_data, reverse=True)
    print("Reverse Sorted:", result_reversed)

import locale
from typing import Callable, List, Optional
class LocaleAwareSorter:
    def __init__(self, custom_key_func: Optional[Callable[[str], str]] = None):
        self.custom_key_func = custom_key_func or (lambda x: x)
    def sort(self, items: List[str]) -> List[str]:
        return sorted(items, key=self._get_sort_key)
    def _get_sort_key(self, item: str) -> tuple:
        if self.custom_key_func is not None:
            processed = self.custom_key_func(item)
            return (processed.lower(), locale.strxfrm(processed))
        return (item, locale.strxfrm(item))
if __name__ == '__main__':
    sample_data = ["apple", "Banana", "cherry", "date"]
    sorter_default = LocaleAwareSorter()
    result_default = sorter_default.sort(sample_data)
    custom_sorter = LocaleAwareSorter(custom_key_func=lambda x: x.upper())
    result_custom = custom_sorter.sort(sample_data)
    print("Default Sort:", result_default)
    print("Custom Upper Case Sort:", result_custom)

