    return filtered
def remove_from_set(items: set, criteria) -> tuple[set]:
    if not isinstance(items, set):
        raise TypeError("Input must be a set.")
    removed = []
    new_items = {}                                                                               
    for item in list(items):
        if not criteria(item):
            items.discard(item)
            removed.append(item)
