from typing import Callable, List, TypeVar
T = TypeVar('T')
def filter_elements(collection: List[T], predicate: Callable[[T], bool]) -> List[T]:
    return [item for item in collection if predicate(item)]
def remove_duplicates_preserve_order(sequence: T) -> List[T]:
    seen = set()
    result = []
    def _is_new(x):
        return x not in seen
    for item in sequence:
        if _is_new(item):
            seen.add(item)
            result.append(item)
    return result
def process_collection(data: List[int]) -> int:
    def is_odd(n: int) -> bool:
        return n % 2 == 1
    filtered = filter_elements(data, lambda x: is_odd(x))
    total = sum(map(lambda item: item * 2, filtered))
    return total
if __name__ == '__main__':
    sample_data = [10, 3, 5, 7, 8, 9]
    result = process_collection(sample_data)
    print(result)

import typing
class FilterUtility:
    @staticmethod
    def filter_list(items: list[typing.Any], predicate: typing.Callable[[typing.Any], bool]) -> list[typing.Any]:
        return [item for item in items if not predicate(item)]
    @staticmethod
    def filter_set(items: set[typing.Any], predicate: typing.Callable[[typing.Any], bool]) -> set[typing.Any]:
        filtered = {item for item in items if not predicate(item)}
        return frozenset(filtered)                                              
    @staticmethod
    def filter_tuple(items: tuple[typing.Any], predicate: typing.Callable[[typing.Any], bool]) -> tuple[typing.Any]:
        filtered = [item for item in items if not predicate(item)]
        return tuple(filtered)
    @staticmethod
    def filter_dict(
        data: dict[str, typing.Any] | list[tuple[typing.Any]], 
        key_predicate: typing.Callable[[str], bool] | None = None,
        value_predicate: typing.Callable[[typing.Any], bool] | None = None
    ) -> dict[str, typing.Any]:
        if isinstance(data, dict):
            result = {}
            for k, v in data.items():
                keep_key = key_predicate is None or not key_predicate(k)
                keep_value = value_predicate is None or not value_predicate(v)
                if keep_key and keep_value:
                    result[k] = v
            return result
        else:
            raise TypeError("Input must be a dictionary.")
    @staticmethod
    def validate_input(data: typing.Any, expected_type: type) -> bool:
        try:
            is_correct = isinstance(data, expected_type)
            return True if is_correct else False
        except Exception as e:
            print(f"Validation Error: {e}")
            raise
if __name__ == '__main__':
    sample_list = [10, 20, 'a', None, 30]
    def is_even(n):
        return isinstance(n, int) and n % 2 == 0
    filtered_result = FilterUtility.filter_list(sample_list, is_even)
    print("Filtered List:", filtered_result)

import functools
from typing import Any, Callable, Dict, Iterable, List, Set, Tuple
class FilterUtils:
    @staticmethod
    def filter_by_value(
        collection: Iterable[Any], predicate: Callable[[Any], bool]
    ) -> List[Any]:
        if not isinstance(collection, (list, tuple)):
            raise TypeError(f"Input must be a list or tuple, got {type(collection)}")
        if not callable(predicate):
            raise TypeError("Predicate function must be callable")
        return [item for item in collection if predicate(item)]
    @staticmethod
    def filter_by_key(
        data: Dict[Any, Any], key_predicate: Callable[[Any], bool]
    ) -> List[Tuple[Any, Any]]:
        if not isinstance(data, dict):
            raise TypeError(f"Input must be a dictionary, got {type(data)}")
        if not callable(key_predicate):
            raise TypeError("Key predicate function must be callable")
        return [(k, v) for k, v in data.items() if key_predicate(k)]
    @staticmethod
    def remove_duplicates_from_list(items: List[Any]) -> Set[Any]:
        if not isinstance(items, list):
            raise TypeError(f"Input must be a list, got {type(items)}")
        return set(items)
    @staticmethod
    def filter_set_by_condition(
        data: Set[Any], condition_fn: Callable[[Any], bool]
    ) -> List[Any]:
        if not isinstance(data, set):
            raise TypeError(f"Input must be a set, got {type(data)}")
        if not callable(condition_fn):
            raise TypeError("Condition function must be callable")
        return [item for item in data if condition_fn(item)]
