def safe_get(data: dict, *keys) -> any:
    current = data
    if not isinstance(current, dict):
        raise TypeError(f"Expected a dictionary, got {type(current).__name__}")
    for key in keys:
        try:
            next_level = current[key]
        except KeyError:
            return None
        if not isinstance(next_level, dict):
            return None
        current = next_level
    return current
