import sys
def sanitize_input(value: str) -> float | None:
    try:
        return float(value.strip()) if value else None
    except ValueError:
        return None
class Logger:
    def __init__(self):
        self.logs = []
    def log(self, level: str, message: str):
        entry = {"level": level, "message": message}
        self.logs.append(entry)
        print(f"[{level}] {message}")
    def get_logs(self) -> list[dict]:
        return self.logs
def calculate_sum(a_str: str | None, b_str: str | None, logger: Logger) -> float | tuple[str, ...]:
    a = sanitize_input(a_str)
    if not isinstance(a, (int, float)):
        raise ValueError("First input is invalid")
    b = sanitize_input(b_str)
    if not isinstance(b, (int, float)):
        raise ValueError("Second input is invalid")
    try:
        result = a + b
        logger.log("INFO", f"Calculated sum of {a} and {b}: {result}")
        return result
    except OverflowError as e:
        error_msg = f"Calculation overflow occurred for inputs {a} and {b}"
        raise ValueError(error_msg) from e
if __name__ == '__main__':
    logger = Logger()
    sample_a_str = "10.5"
    sample_b_str = "-3.2"
    try:
        result = calculate_sum(sample_a_str, sample_b_str, logger)
        print(f"\nFinal Result: {result}")
    except ValueError as e:
        error_logs = logger.get_logs()
        for log in reversed(error_logs):
            if "error" in log["level"].lower():
                logger.log(log["level"], f"{e.args[0]}")

import sys
def sanitize_input(value: str) -> float | None:
    try:
        return float(value.strip()) if value else 0.0
    except ValueError:
        print(f"Error: Invalid numeric input '{value}'")
        return None
class Logger:
    def __init__(self, log_file=None):
        self.log_file = open(log_file or "calculator_log.txt", "a")
    def info(self, message: str) -> None:
        timestamp = f"[{sys.argv[0]}] {message}" if sys.argv else f"INFO: {message}"
        print(timestamp)
        self.log_file.write(f"{timestamp}\n")
        self.log_file.flush()
    def error(self, message: str) -> None:
        timestamp = f"[ERROR] {message}"
        print(timestamp)
        self.log_file.write(f"{timestamp}\n")
        self.log_file.flush()
def calculate_sum(a: float | int, b: float | int) -> tuple[float, bool]:
    try:
        result = a + b
        return result, True
    except Exception as e:
        print(f"Calculation failed due to error: {e}")
        Logger().error(str(e))
        return 0.0, False
if __name__ == '__main__':
    logger = Logger()
    sample_a_str = "123456789.12345"
    sample_b_str = "-987654321.98765"
    a_val = sanitize_input(sample_a_str) or 0.0
    b_val = sanitize_input(sample_b_str) or 0.0
    logger.info(f"Processing inputs: {a_val} and {b_val}")
    final_result, success = calculate_sum(a_val, b_val)
    if not success:
        sys.exit(1)
    print(f"Sum of {sample_a_str} + {sample_b_str} = {final_result:.5f}")

import sys
from datetime import datetime
class SumCalculator:
    def sanitize_input(self, value):
        try:
            num = float(value)
            if not (num > -1e308 and num < 1e308):
                raise ValueError("Number out of range")
            return num
        except Exception as e:
            self.log_error(f"Sanitization failed for input '{value}': {str(e)}", "SANITIZATION_ERROR")
            sys.exit(1)
    def calculate_sum(self, a, b):
        try:
            result = float(a + b)
            if not (result > -1e308 and result < 1e308):
                raise ValueError("Result out of range")
            return result
        except Exception as e:
            self.log_error(f"Calculation failed for inputs {a} and {b}: {str(e)}", "CALCULATION_ERROR")
            sys.exit(1)
    def log_message(self, message):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        print(f"[{timestamp}] INFO: {message}")
    def log_error(self, error_msg, error_type="ERROR"):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        print(f"[{timestamp}] [{error_type}]: {error_msg}", file=sys.stderr)
def main():
    calculator = SumCalculator()
    sample_a = "10.5"
    sample_b = "-3.2"
    try:
        num_a = calculator.sanitize_input(sample_a)
        num_b = calculator.sanitize_input(sample_b)
        result = calculator.calculate_sum(num_a, num_b)
        message = f"The sum of {num_a} and {num_b} is {result}"
        calculator.log_message(message)
    except Exception as e:
        error_type = "UNKNOWN_ERROR" if not isinstance(e, ValueError) else "VALUE_ERROR"
        calculator.log_error(f"{str(e)}", error_type=error_type)
if __name__ == '__main__':
    main()

