    end_time = time.time()
    print(f"Processing completed in {end_time - start_time:.4f} seconds")
    if 'only_in_first' in result:
        for item in result['only_in_first']:
            print(item)
    if 'only_in_second' in result:
        for item in result['only_in_second']:
