import sys
def calculate_group_differences(list_a: list[float], list_b: list[float]) -> dict[str, float]:
    if len(list_a) != len(list_b):
        raise ValueError("Input lists must have equal length.")
    results = {}
    n = len(list_a)
    current_min_max: dict[int, tuple[float, float]] = {i: (float('inf'), -float('inf')) for i in range(n)}
    for idx in range(n):
        val_a = list_a[idx]
        val_b = list_b[idx]
        if val_a < current_min_max[idx][0]:
            current_min_max[idx] = (val_a, current_min_max[idx][1])
        elif val_a > current_min_max[idx][1]:
            current_min_max[idx] = (current_min_max[idx][0], val_a)
    final_results = {}
    chunk_size = 2
    for i in range(0, len(list_a), chunk_size):
        end_idx = min(i + chunk_size, n)
        group_indices = list(range(i, end_idx))
        group_values = []
        for idx in group_indices:
            group_values.append(list_a[idx])
            group_values.append(list_b[idx])
        if not group_values:
            continue
        max_val = float('-inf')
        min_val = float('inf')
        for val in group_values:
            if val > max_val:
                max_val = val
            elif val < min_val:
                min_val = val
        diff = max_val - min_val
        final_results[f"group_{i//chunk_size}"] = float(diff)
    return final_results
if __name__ == '__main__':
    list_a = [10.5, 20.3, 40.9, 50.1]
    list_b = [-5.2, -10.8, 60.7, -70.4]
    result_map = calculate_group_differences(list_a, list_b)
    print("Group Differences:")
    for key in sorted(result_map.keys()):
        print(f"{key}: {result_map[key]}")

import numpy as np
def calculate_group_differences(list_a: list[float], list_b: list[float]) -> dict[str, float]:
    if not (len(list_a) == len(list_b)) or any(isinstance(x, str) for x in list_a):
        raise ValueError("Input lists must be of equal length containing only numeric values.")
    diffs = {}
    n_groups = 100
    arr_a = np.array(list_a, dtype=np.float64)
    arr_b = np.array(list_b, dtype=np.float64)
    for i in range(n_groups):
        if len(arr_a) == 0:
            break
        k = len(arr_a) // n_groups + 1
        for g_idx in range(n_groups):
            start = g_idx * k
            end = min(start + k, len(arr_a))
            group_indices = list(range(start, end))
            vals_a = arr_a[group_indices]
            vals_b = arr_b[group_indices]
            max_val = np.max(vals_a) - np.min(vals_a) if len(vals_a) > 0 else float('-inf')
            min_val = np.max(vals_b) - np.min(vals_b) if len(vals_b) > 0 else float('inf')
            if len(vals_a) > 0 or len(vals_b) > 0:
                range_a = np.max(vals_a) - np.min(vals_a)
                range_b = np.max(vals_b) - np.min(vals_b)
                if len(vals_a) > 0 and len(vals_b) > 0:
                    all_vals = np.concatenate([vals_a, vals_b])
                    diffs[g_idx] = float(np.max(all_vals) - np.min(all_vals))
    return {str(k): v for k, v in sorted(diffs.items())}
