    sample_list_a = [10.5, 23.4, -5.6, 999.9]
    sample_list_b = [-1.2, 87.1, 0.0, 1000.0]
    result = group_parallel_lists(sample_list_a, sample_list_b)
    for item in result:
        print(f"Group {item['index']}: Values={item['values']}, Range={item['range']}")

