from typing import Set
class ThreadSafeSetDiff:
    def __init__(self):
        self._lock = threading.Lock()
    def symmetric_difference(self, set_a: Set[int], set_b: Set[int]) -> Set[int]:
        with self._lock:
            return (set_a - set_b) | (set_b - set_a)
