    for item in unique_elements:
        count = 0
        for lst in lists:
            if item in lst:
                count += 1
        if count == 1:
            result_set.add(item)
    return sorted(result_set, key=lambda x: (isinstance(x, str), -ord(x[0]) if isinstance(x, str) else hash(x)))
