def find_diff_indices_pure(a: list, b: list) -> list:
    if len(a) != len(b):
        raise ValueError("Input lists must have the same length.")
    result = []
    for i in range(len(a)):
        if a[i] != b[i]:
            result.append(i)
    return result
def find_diff_indices_numpy(arr1: list, arr2: list) -> np.ndarray:
    arr1 = np.array(arr1)
    arr2 = np.array(arr2)
    if len(arr1.shape) != 0 and len(arr2.shape) == 0:
        diff_mask = (arr1 != arr2).flatten()
    else:
        diff_mask = arr1 != arr2
    return np.where(diff_mask)[0]
def compare_arrays(a: list, b: list, use_numpy: bool = True) -> any:
    if len(a) == 0 or len(b) == 0:
        raise ValueError("Input lists cannot be empty.")
    if not (len(a) == len(b)):
        raise ValueError(f"Arrays must have the same length. Got {len(a)} vs {len(b)}.")
    return find_diff_indices_numpy(arr1=a, arr2=b)
if __name__ == '__main__':
    sample_a = [10, 20, 30, 40, 50]
    sample_b = [10, 25, 30, 90, 60]
    indices = compare_arrays(sample_a, sample_b)
    print("Indices where values differ:", list(indices))

import numpy as np
def find_differences_numpy(arr1: list | tuple | np.ndarray, arr2: list | tuple | np.ndarray) -> list[int]:
    a = np.array(arr1)
    b = np.array(arr2)
    return [np.where(a != b)[0].tolist()]
def find_differences_python(arr1: list | tuple, arr2: list | tuple) -> list[int]:
    result = []
    for i in range(len(arr1)):
        if arr1[i] != arr2[i]:
            result.append(i)
    return result
if __name__ == '__main__':
    sample_arr_1 = [1, 5, 3, 7, 9]
    sample_arr_2 = [1, 4, 3, 8, 9]
    print("NumPy Result:", find_differences_numpy(sample_arr_1, sample_arr_2))
    print("Python Result:", find_differences_python(sample_arr_1, sample_arr_2))

import numpy as np
def find_diff_indices_pure_python(arr1: list, arr2: list) -> list:
    return [i for i, (a, b) in enumerate(zip(arr1, arr2)) if a != b]
def find_diff_indices_numpy(arr1: np.ndarray, arr2: np.ndarray) -> list:
    diff_mask = arr1 != arr2
    return [np.where(diff_mask)[0].tolist()] if any(diff_mask) else []
def find_diff_indices(arr1, arr2):
    try:
        np_arr1 = np.array(arr1)
        np_arr2 = np.array(arr2)
        return find_diff_indices_numpy(np_arr1, np_arr2)[0] if isinstance(find_diff_indices_numpy(np_arr1, np_arr2), list) else []
    except Exception:
        return find_diff_indices_pure_python(arr1, arr2)
if __name__ == '__main__':
    sample_array_1 = [1.5, 3.0, 4.5, 6.0]
    sample_array_2 = [1.5, 7.0, 4.5, 8.0]
    result_indices = find_diff_indices(sample_array_1, sample_array_2)
    print(result_indices)

class IntegerMultiplier:
    def __init__(self):
        pass
    def validate_int(self, value) -> bool:
        return isinstance(value, int) and not isinstance(value, type(True))
    def multiply(self, a: int, b: int) -> int:
        if self.validate_int(a) and self.validate_int(b):
            return a * b
        else:
            raise TypeError("Both arguments must be integers.")
    def multiply_safe(self, a: int | float = None, b: int | float = None) -> int | None:
        default_a = a if self.validate_int(a) else 0
        default_b = b if self.validate_int(b) else 1
        return self.multiply(default_a, default_b)
if __name__ == '__main__':
    multiplier = IntegerMultiplier()
    num_1: int = 42
    num_2: int = -7
    try:
        result = multiplier.multiply(num_1, num_2)
        print(f"Result of {num_1} * {num_2}: {result}")
    except TypeError as e:
        print(f"Error during multiplication: {e}")

