def multiply_integers(a: object, b: object) -> int:
    a = int(a) if not isinstance(a, int) else a
    b = int(b) if not isinstance(b, int) else b
    return a * b
if __name__ == '__main__':
    print(multiply_integers(3.5, 4))

def multiply_integers(a: int | float = None, b: int | float = None) -> int:
    if a is not None and (not isinstance(a, int)):
        try:
            a = int(float(a))
        except ValueError:
            raise TypeError("Input 'a' must be convertible to an integer")
    elif a is None:
        a = 0
    if b is not None and (not isinstance(b, int)):
        try:
            b = int(float(b))
        except ValueError:
            raise TypeError("Input 'b' must be convertible to an integer")
    elif b is None:
        b = 0
    return a * b
