    test_cases = [
        (10, 2),
        (-5, -3),
        (0.5, 4),
        ("five", "two"),
        (10, 0),
        ("ten", 2)
    ]
    for num in test_cases:
        if len(num) == 2:
            try:
                result = safe_divide(*num)
                print(f"{num[0]} / {num[1]} = {result}")
            except (TypeError, ZeroDivisionError) as e:
                print(f"Error for input ({num}): {type(e).__name__}: {e}")

def divide_numbers(a: float, b: float) -> float:
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise TypeError("Both operands must be numeric types.")
    try:
        a = float(a)
        b = float(b)
    except ValueError:
        raise ValueError("Operands cannot be converted to valid numbers.")
    if b == 0.0:
        raise ZeroDivisionError("Cannot divide by zero.")
    return a / b
