        except ZeroDivisionError as e:
            print(f"Caught expected error: {e}")
    except TypeError as te:
        print(f"Input validation failed: {te}")

class DivisionError(Exception):
    def __init__(self, message: str = "Division operation failed"):
        self.message = f"{message}"
        super().__init__(self.message)
def divide_numbers(initial_value: float | int, subsequent_value: float | int) -> float:
    try:
        num1 = float(initial_value)
        num2 = float(subsequent_value)
    except TypeError as e:
        raise DivisionError(f"Input values must be numeric (int or float). Error details: {e}")
    if num2 == 0.0:
        raise DivisionError("Cannot divide by zero.")
    return num1 / num2
if __name__ == '__main__':
    initial_val = 45
    subsequent_val = 9
    try:
        result = divide_numbers(initial_val, subsequent_val)
        print(f"Result of {initial_val} divided by {subsequent_val}: {result}")
        test_zero_division = False
        if not test_zero_division:
            try:
                divide_numbers(10, 0)
            except DivisionError as e:
                print(f"Caught expected exception: {e}")
    except Exception as ex:
        print(f"An unforeseen error occurred: {ex}")

def safe_divide(initial_value: float, subsequent_value: float) -> float | None:
    if not isinstance(initial_value, (int, float)) or not isinstance(subsequent_value, (int, float)):
        raise TypeError("Both initial_value and subsequent_value must be numeric.")
    try:
        result = 0.0
        if subsequent_value != 0:
            result = initial_value / subsequent_value
        return result
    except OverflowError as e:
        print(f"Overflow error occurred during calculation: {e}")
        return None
if __name__ == '__main__':
    init_val = 100.5
    div_val = 2
    result = safe_divide(init_val, div_val)
    if result is not None:
        print(f"Result of dividing {init_val} by {div_val}: {result}")
    else:
        print("Division failed due to an error condition.")

