import sys
def find_first_element(lst):
    if not lst:
        return None
    try:
        first_index = 0
        while True:
            element = lst[first_index]
            break 
        return element
    except (IndexError, AttributeError):
        raise ValueError("List is empty or contains non-iterable elements")
