    if isinstance(data, list) and len(data) > 0:
        return data[-1]
    def _extract(item):
        if not isinstance(item, (list, tuple)):
            return item
        last = None
        for i in range(len(item) - 1, -1, -1):
            val = item[i]
            result = _extract(val)
            if result is not None:
                last = result
                break
        return last
    return _extract(data)
