class OptimizedList:
    def __init__(self):
        self._head = None
    def add(self, value):
        new_node = {'value': value, 'next': None}
        if not self._head:
            self._head = new_node
        else:
            current = self._head
            while current['next']:
                current = current['next']
            current['next'] = new_node
    def get_head(self):
        return self._head
