import numpy as np
def find_center_mark(data):
    if data is None:
        return 0
    try:
        arr = np.array(data)
        length = len(arr)
        if length == 0:
            return 0
        center_index = (length - 1) // 2
        return int(center_index)
    except Exception:
        raise ValueError("Input must be convertible to a sequence.")
